const clientStorageKey="pcl-crm-clients-v1",lifecycleStorageKey="pcl-crm-engagements-v1",firmStorageKey="pcl-crm-firms-v1";
function loadRecords(key){try{return JSON.parse(localStorage.getItem(key))||[]}catch{return[]}}
const initialFirmDirectory=[
  {id:"firm-1",legalName:"Firm 1",firmCode:"FIRM-1",isActive:true},
  {id:"firm-2",legalName:"Firm 2",firmCode:"FIRM-2",isActive:true},
  {id:"firm-3",legalName:"Firm 3",firmCode:"FIRM-3",isActive:true}
];
let firms=loadRecords(firmStorageKey);
if(!firms.length){firms=initialFirmDirectory.map(firm=>({...firm}));localStorage.setItem(firmStorageKey,JSON.stringify(firms))}
let clients=loadRecords(clientStorageKey),lifecycleRecords=loadRecords(lifecycleStorageKey);
function saveFirms(){localStorage.setItem(firmStorageKey,JSON.stringify(firms))}
function saveClients(){localStorage.setItem(clientStorageKey,JSON.stringify(clients))}
function saveLifecycleRecords(){localStorage.setItem(lifecycleStorageKey,JSON.stringify(lifecycleRecords))}
function activeFirms(){return firms.filter(firm=>firm.isActive!==false)}
function defaultFirm(){return activeFirms()[0]||firms[0]||null}
function firmById(id){return firms.find(firm=>firm.id===id)}
function firmLabel(id){const firm=firmById(id);return firm?`${firm.legalName}${firm.firmCode?` (${firm.firmCode})`:""}`:"Firm not configured"}
function setFirmOptions(id,placeholder="Select handling firm…",selectedValue){const target=document.getElementById(id);if(!target)return;const current=selectedValue??target.value;target.innerHTML=`<option value="">${escapeHtml(placeholder)}</option>${activeFirms().map(firm=>`<option value="${escapeHtml(firm.id)}">${escapeHtml(firmLabel(firm.id))}</option>`).join("")}`;if([...target.options].some(option=>option.value===current))target.value=current}
function migrateFirmOwnership(){const fallback=defaultFirm();if(!fallback)return;let clientsChanged=false,leadsChanged=false;clients.forEach(client=>{if(!client.firmId){client.firmId=fallback.id;clientsChanged=true}});lifecycleRecords.forEach(record=>{if(!record.firmId){record.firmId=fallback.id;leadsChanged=true}});if(clientsChanged)saveClients();if(leadsChanged)saveLifecycleRecords()}
migrateFirmOwnership();
function escapeHtml(value=""){return String(value).replace(/[&<>'"]/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[character])}
function numberOrNull(value){return value===""||value===null||value===undefined?null:Number(value)}
function valueOrEmpty(value){return value===null||value===undefined?"":value}
function formatKes(value){return value===null||value===undefined?"Not calculated":`KES ${Number(value).toLocaleString(undefined,{maximumFractionDigits:2})}`}
function setOptions(id,items,placeholder="Select…"){document.getElementById(id).innerHTML=`<option value="">${escapeHtml(placeholder)}</option>${items.map(item=>`<option value="${escapeHtml(item)}">${escapeHtml(item)}</option>`).join("")}`}
function allServices(){return Object.values(CRM.serviceGroups).flat()}
function selectedServices(){return[...document.querySelectorAll('input[name="services"]:checked')].map(input=>input.value)}
function selectedTaxWorkPacks(){return[...document.querySelectorAll('input[name="taxWorkPack"]:checked')].map(input=>input.value)}
function hasTaxCompliance(){return selectedServices().includes("Tax Compliance (VAT, PAYE, Income Tax)")}

function renderStaticFields(){
  setFirmOptions("clientFirm","Select initial servicing firm…");setFirmOptions("leadHandlingFirm","Select handling firm…");setOptions("primarySector",CRM.sectors,"Select sector…");setOptions("branchLocation",CRM.branches,"Select branch…");setOptions("clientCategory",CRM.clientCategories,"Select category…");setOptions("leadSource",CRM.leadSources,"Select lead source…");setOptions("decisionRole",CRM.decisionRoles,"Select role…");setOptions("billingFrequency",CRM.billingFrequencies,"Select frequency…");setOptions("pipelineStage",CRM.pipelineStages,"Select stage…");setOptions("etimsStatus",CRM.etimsStatuses,"Select status…");setOptions("finalStockStatus",CRM.finalStockStatuses,"Select status…");setOptions("instalmentMethod",CRM.instalmentMethods,"Select method…");
  setOptions("leadPrimarySector",CRM.sectors,"Select sector…");setOptions("leadBranchLocation",CRM.branches,"Select branch…");setOptions("lifecycleLeadSource",CRM.leadSources,"Select lead source…");setOptions("leadService",allServices(),"Select initial service…");setOptions("bundleService",allServices(),"No bundled service");
  document.getElementById("regulatoryBodies").innerHTML=CRM.regulators.map(regulator=>`<label><input type="checkbox" name="regulator" value="${escapeHtml(regulator)}" />${escapeHtml(regulator)}</label>`).join("");
  document.getElementById("taxRegistrations").innerHTML=CRM.taxRegistrations.map(registration=>`<label><input type="checkbox" name="taxRegistration" value="${escapeHtml(registration)}" />${escapeHtml(registration)}</label>`).join("");
  document.getElementById("taxWorkPacks").innerHTML=CRM.taxWorkPacks.map(workPack=>`<label><input type="checkbox" name="taxWorkPack" value="${escapeHtml(workPack.id)}" />${escapeHtml(workPack.label)}</label>`).join("");
  document.getElementById("servicePicker").innerHTML=Object.entries(CRM.serviceGroups).map(([group,services])=>`<section class="service-group"><strong>${escapeHtml(group)}</strong><div class="service-options">${services.map(service=>`<label><input type="checkbox" name="services" value="${escapeHtml(service)}" />${escapeHtml(service)}</label>`).join("")}</div></section>`).join("");
  document.getElementById("serviceCatalog").innerHTML=Object.entries(CRM.serviceGroups).map(([group,services])=>`<section class="card catalog-section"><h3>${escapeHtml(group)}</h3><ul>${services.map(service=>`<li>${escapeHtml(service)}</li>`).join("")}</ul></section>`).join("");
  document.getElementById("sectorMatrix").innerHTML=Object.entries(CRM.sectorSuggestions).map(([sector,services])=>`<section class="card catalog-section"><h3>${escapeHtml(sector)}</h3><p class="hint">Recommended controlled service tags</p><ul>${services.map(service=>`<li>${escapeHtml(service)}</li>`).join("")}</ul></section>`).join("");
}
function renderAccessControl(){
  const hierarchyRows=CRM.accessRoles.map(role=>`<tr><td>${escapeHtml(role.level)}</td><td><b>${escapeHtml(role.position)}</b></td><td>${escapeHtml(role.visibility)}</td><td>${escapeHtml(role.scope)}</td></tr>`).join(""),profileRows=CRM.permissionProfiles.map(profile=>`<tr><td><b>${escapeHtml(profile.position)}</b><br><span class="hint">${escapeHtml(profile.profile)}</span></td><td>${escapeHtml(profile.rights)}</td><td>${escapeHtml(profile.restrictions)}</td></tr>`).join("");
  const firmRows=firms.map(firm=>`<tr><td><b>${escapeHtml(firm.legalName)}</b><br><span class="hint">${escapeHtml(firm.firmCode)}</span></td><td>${firm.isActive!==false?"Active":"Inactive"}</td><td><button type="button" data-firm-action="edit" data-id="${firm.id}">Edit</button></td></tr>`).join("");
  document.getElementById("accessControl").innerHTML=`<div class="section"><div class="section-heading"><h3>Firm directory and ownership controls</h3><span class="hint">Select a firm once on the lead; a different firm requires a separate engagement.</span></div><div class="operations-layout"><form id="firmForm" class="form-card"><div class="grid"><label>Legal firm name <span>*</span><input required id="firmLegalName" name="firmLegalName" placeholder="Enter legal operating-firm name" /></label><label>Firm code <span>*</span><input required id="firmCode" name="firmCode" placeholder="Short unique code" /></label></div><div class="actions"><button class="btn primary" type="submit">Add firm</button></div></form><div class="table-wrap"><table class="access-table"><thead><tr><th>Firm</th><th>Status</th><th>Action</th></tr></thead><tbody>${firmRows}</tbody></table></div></div><p class="hint">Before live use, replace the three placeholder firms with the legal entities and restrict users through firm-access rules. The browser keeps an engagement’s firm immutable.</p></div><div class="section"><div class="section-heading"><h3>Role hierarchy and data visibility</h3><span class="hint">Higher positions inherit visibility of their assigned lower teams</span></div><table class="access-table"><thead><tr><th>Level</th><th>Position</th><th>Visibility</th><th>Record scope</th></tr></thead><tbody>${hierarchyRows}</tbody></table></div><div class="section"><div class="section-heading"><h3>Permission profiles</h3><span class="hint">Assign these profiles to authenticated users by position</span></div><table class="access-table"><thead><tr><th>Position / profile</th><th>Permitted actions</th><th>Restrictions</th></tr></thead><tbody>${profileRows}</tbody></table></div><div class="section"><div class="section-heading"><h3>Protected fields and actions</h3><span class="hint">Apply these rules in the server-side permission layer</span></div><table class="access-table"><thead><tr><th>Control</th><th>Engagement Partner</th><th>Manager</th><th>Audit Supervisor</th><th>Audit Assistant</th><th>Intern</th></tr></thead><tbody><tr><td>Engagement Fee</td><td>Read / write</td><td>Read / write</td><td>Hidden</td><td>Hidden</td><td>Hidden</td></tr><tr><td>EQR Completed</td><td>Read / write</td><td>Read-only</td><td>Read-only</td><td>Read-only</td><td>Hidden</td></tr><tr><td>PIE Client Won / Audit Signed</td><td>May move after EQR</td><td>Read-only</td><td>Read-only</td><td>Read-only</td><td>Hidden</td></tr><tr><td>Lead-to-engagement approval</td><td>Approves PIE and threshold proposals; activates engagements</td><td>Performs scoping, verifies KYC and activates standard engagements</td><td>Read-only</td><td>Read-only</td><td>Hidden</td></tr><tr><td>Firm ownership</td><td>May manage firm directory and cross-firm access</td><td>May act only for assigned firms</td><td>Assigned-firm records only</td><td>Assigned-firm records only</td><td>Assigned task firm only</td></tr><tr><td>Export client data</td><td>Allowed</td><td>Allowed for assigned teams</td><td>Not allowed</td><td>Not allowed</td><td>Not allowed</td></tr><tr><td>Delete client record</td><td>Allowed</td><td>Not allowed</td><td>Not allowed</td><td>Not allowed</td><td>Not allowed</td></tr></tbody></table></div>`;
}

function initialiseFirmManagement(){const root=document.getElementById("accessControl");root.addEventListener("submit",event=>{if(event.target.id!=="firmForm")return;event.preventDefault();const data=new FormData(event.target),legalName=data.get("firmLegalName").trim(),firmCode=data.get("firmCode").trim().toUpperCase();if(firms.some(firm=>firm.firmCode.toUpperCase()===firmCode)){alert("Firm code already exists. Use a unique code.");return}firms.push({id:crypto.randomUUID(),legalName,firmCode,isActive:true,createdAt:new Date().toISOString()});saveFirms();renderStaticFields();renderAccessControl();alert(`${legalName} added to the firm directory.`)});root.addEventListener("click",event=>{const button=event.target.closest("button[data-firm-action]");if(!button)return;const firm=firmById(button.dataset.id);if(!firm)return;const legalName=prompt("Legal firm name:",firm.legalName);if(!legalName)return;const firmCode=prompt("Unique firm code:",firm.firmCode);if(!firmCode)return;if(firms.some(item=>item.id!==firm.id&&item.firmCode.toUpperCase()===firmCode.trim().toUpperCase())){alert("Firm code already exists. Use a unique code.");return}firm.legalName=legalName.trim();firm.firmCode=firmCode.trim().toUpperCase();saveFirms();renderStaticFields();renderAccessControl()})}

function showTaxComplianceProfile(){document.getElementById("taxComplianceProfile").hidden=!hasTaxCompliance()}
function showRecommendation(){const sector=document.getElementById("primarySector").value,target=document.getElementById("serviceRecommendation"),recommended=CRM.sectorSuggestions[sector];if(!recommended){target.innerHTML="Choose a Primary Sector to view its recommended standard service tags.";return}target.innerHTML=`<b>${escapeHtml(sector)} recommendation:</b> ${recommended.map(escapeHtml).join(", ")}. <button type="button" id="applyRecommendations">Apply these tags</button>`;document.getElementById("applyRecommendations").addEventListener("click",()=>{document.querySelectorAll('input[name="services"]').forEach(input=>input.checked=recommended.includes(input.value));showTaxComplianceProfile();showNotice(`Applied ${sector} recommended service tags. Review and amend them for this engagement before saving.`)})}
function requiresIeQr(client){return !client.smeAuditExempt&&(client.pieStatus||["Financial Services","Public Sector"].includes(client.primarySector))}
function addTaxTask(tasks,client,id,title,owner="Tax team",control={}){tasks.push({id:`tax-${id}`,title,owner,status:"Not started",category:"Tax Compliance",taxPeriod:client.taxProfile.reportingMonth||"Not set",evidenceLocation:"",itaxStatus:control.itaxStatus||"Not applicable",reviewerApproval:control.reviewerApproval||"Not required",postingStatus:control.postingStatus||"Not applicable",control})}
function annualReturnAnniversary(incorporationDate,asOf=operationDate()){if(!incorporationDate)return null;const incorporated=new Date(`${incorporationDate}T00:00:00Z`),reference=new Date(`${asOf}T00:00:00Z`);if(Number.isNaN(incorporated.getTime())||Number.isNaN(reference.getTime()))return null;const anniversaryFor=year=>{const month=incorporated.getUTCMonth(),lastDay=new Date(Date.UTC(year,month+1,0)).getUTCDate(),day=Math.min(incorporated.getUTCDate(),lastDay);return new Date(Date.UTC(year,month,day))};let anniversary=anniversaryFor(reference.getUTCFullYear());if(anniversary<reference)anniversary=anniversaryFor(reference.getUTCFullYear()+1);return anniversary.toISOString().slice(0,10)}
function addStatutoryComplianceTasks(tasks,client){const anniversary=annualReturnAnniversary(client.incorporationDate);if(anniversary){const activation=new Date(`${anniversary}T00:00:00Z`);activation.setUTCDate(activation.getUTCDate()-30);const activateOn=activation.toISOString().slice(0,10),isOpen=operationDate()>=activateOn;tasks.push({id:`brs-annual-return-${anniversary}`,templateCode:"BRS_ANNUAL_RETURN_FILING",title:"BRS Annual Return Filing",owner:"Practice Administration",status:isOpen?"Open":"Scheduled",category:"Statutory Compliance",dueDate:anniversary,activateOn,evidenceCategory:"brs-acknowledgements",evidenceRule:"Upload the BRS acknowledgement receipt to the locked BRS Acknowledgment Receipts folder."})}if(client.etimsOnboardingRequired||(client.taxProfile&&client.taxProfile.etimsStatus==="Not registered")){tasks.push({id:"etims-onboarding",templateCode:"ETIMS_ONBOARDING",title:"eTIMS Onboarding",owner:"Tax Manager",status:"Open",category:"Statutory Compliance",evidenceRule:"Retain onboarding confirmation and related tax evidence in the controlled Tax Returns folder."})}}
function generateWorkflows(client){
  const tasks=[];if(requiresIeQr(client))tasks.push({id:"ieqr",title:"Assign Independent Engagement Quality Reviewer",owner:"Engagement Partner",status:"Pending Engagement Partner",gate:true});tasks.push({id:"routing",title:`Route lead to ${CRM.branchRouting[client.branchLocation]}`,owner:CRM.branchRouting[client.branchLocation],status:"Open"});
  if(client.smeAuditExempt&&client.services.includes("Statutory Audit"))tasks.push({id:"sme-audit-exempt",title:"Record SME Audit Exemption Basis",owner:"Engagement Partner",status:"Control recorded",category:"Statutory Compliance",gate:true,evidenceRule:"Do not generate or perform the statutory-audit workflow while this exemption is active."});
  if(client.taxProfile){const packs=client.taxProfile.workPacks;addTaxTask(tasks,client,"setup","Confirm KRA PIN, registrations, financial year, reporting month, tax rate and opening balances","Tax Manager",{reviewerApproval:"Pending"});
    if(packs.includes("vat")){addTaxTask(tasks,client,"vat-source","Collect eTIMS sales, Z reports, bank statements, sales evidence and purchase data");addTaxTask(tasks,client,"vat-sales-banking","Reconcile eTIMS sales, Z reports, bank deposits and documented non-sales receipts");addTaxTask(tasks,client,"vat-purchases","Classify eTIMS purchases at 16%, 8%, zero-rated or exempt and route each item to COGS, expenditure or PPE");addTaxTask(tasks,client,"vat-return","Prepare output VAT, input VAT, opening-credit and adjustment control","Tax Associate",{reviewerApproval:"Pending"});addTaxTask(tasks,client,"vat-file","Obtain review, file VAT return and retain acknowledgement, PRN and payment evidence","Tax Manager",{itaxStatus:"Pending verification",reviewerApproval:"Pending"})}
    if(packs.includes("payroll")){addTaxTask(tasks,client,"payroll-input","Collect payroll register, casual-wage records and statutory payment evidence");addTaxTask(tasks,client,"payroll-reconcile","Reconcile payroll and GL to PAYE, NSSF, SHIF, AHL and NITA statutory totals");addTaxTask(tasks,client,"payroll-file","Prepare, review and file PAYE and applicable statutory returns, then retain payment evidence","Tax Manager",{itaxStatus:"Pending verification",reviewerApproval:"Pending"})}
    if(packs.includes("wht")){addTaxTask(tasks,client,"wht-review","Review professional-service payments, resident status, WHT code, rate and supporting evidence");addTaxTask(tasks,client,"wht-file","Prepare WHT return and payment, then retain certificates and iTax evidence","Tax Manager",{itaxStatus:"Pending verification",reviewerApproval:"Pending"})}
    if(packs.includes("credits")){addTaxTask(tasks,client,"credit-register","Enter VAT adjustments, WHT credits, instalment payments and balance payments in the Tax Credit Register","Tax Associate",{itaxStatus:"Pending verification",reviewerApproval:"Pending",postingStatus:"Blocked"});addTaxTask(tasks,client,"credit-post","Post a tax credit or prepayment only after iTax verification and reviewer approval","Tax Manager",{itaxStatus:"Required",reviewerApproval:"Required",postingStatus:"Blocked pending approval"})}
    if(packs.includes("incomeTax")){addTaxTask(tasks,client,"tb-map","Map GL/TB balances to tax treatment and investigate unsupported, non-deductible or exceptional expenditure");addTaxTask(tasks,client,"income-tax","Prepare provisional taxable-profit and income-tax estimate after the supported tax adjustments","Tax Manager",{reviewerApproval:"Pending"})}
    if(packs.includes("ppe"))addTaxTask(tasks,client,"ppe","Confirm asset class, first use, business use, tax WDV and capital-allowance support","Tax Associate",{reviewerApproval:"Pending"});if(packs.includes("stock"))addTaxTask(tasks,client,"stock","Review gross margin and closing stock, then obtain final stock count and costing before finalising income tax","Client / Tax Associate",{reviewerApproval:"Pending"});if(packs.includes("instalment"))["Month 4","Month 6","Month 9","Month 12"].forEach(month=>addTaxTask(tasks,client,`instalment-${month.replace(" ","").toLowerCase()}`,`${month}: calculate instalment tax, obtain approval, confirm payment and record it as a tax prepayment`,"Tax Manager",{itaxStatus:"Pending verification",reviewerApproval:"Pending",postingStatus:"Blocked pending approval"}));if(packs.includes("report")){addTaxTask(tasks,client,"findings","Review open tax findings, exceptions and TB control before reporting","Tax Manager",{reviewerApproval:"Pending"});addTaxTask(tasks,client,"report","Approve and issue the client tax report with the next-period action list","Tax Manager",{reviewerApproval:"Pending"})}}
  addStatutoryComplianceTasks(tasks,client);if(client.isSacco)tasks.push({id:"sasra",title:"Start SASRA annual reporting readiness — 60 days before applicable deadline",owner:"Financial Services team",status:"Recurring"});return tasks
}
function normaliseName(value){return String(value||"").toLowerCase().replace(/[^a-z0-9]/g,"")}
function findPotentialDuplicate(companyName,tradingName){const names=[normaliseName(companyName),normaliseName(tradingName)].filter(Boolean);return clients.find(client=>[client.companyName,client.tradingName].map(normaliseName).some(name=>name&&names.includes(name)))}
function buildClient(form){const data=new FormData(form),companyName=data.get("companyName").trim(),tradingName=data.get("tradingName").trim(),services=selectedServices(),taxProfile=services.includes("Tax Compliance (VAT, PAYE, Income Tax)")?{registrations:data.getAll("taxRegistration"),etimsStatus:data.get("etimsStatus"),reportingMonth:data.get("taxReportingMonth"),financialYearStart:data.get("taxYearStart"),financialYearEnd:data.get("taxYearEnd"),corporationTaxRate:numberOrNull(data.get("corporationTaxRate")),openingVatCredit:numberOrNull(data.get("openingVatCredit")),openingStock:numberOrNull(data.get("openingStock")),finalStockStatus:data.get("finalStockStatus"),instalmentMethod:data.get("instalmentMethod"),priorYearTax:numberOrNull(data.get("priorYearTax")),currentYearTaxForecast:numberOrNull(data.get("currentYearTaxForecast")),expectedWhtCredits:numberOrNull(data.get("expectedWhtCredits")),workingPaper:data.get("taxWorkingPaper").trim(),workPacks:selectedTaxWorkPacks()}:null,client={id:crypto.randomUUID(),createdAt:new Date().toISOString(),companyName,tradingName,firmId:data.get("clientFirm"),primarySector:data.get("primarySector"),branchLocation:data.get("branchLocation"),regulators:data.getAll("regulator"),pieStatus:data.get("pieStatus")==="on",isSacco:data.get("isSacco")==="on",clientCategory:data.get("clientCategory"),leadSource:data.get("leadSource"),contact:{name:data.get("contactName").trim(),jobTitle:data.get("jobTitle").trim(),email:data.get("email").trim(),phone:data.get("phone").trim(),decisionRole:data.get("decisionRole")},services,engagementValue:data.get("engagementValue")?Number(data.get("engagementValue")):null,billingFrequency:data.get("billingFrequency"),pipelineStage:data.get("pipelineStage"),engagementLetter:data.get("engagementLetter").trim(),notes:data.get("notes").trim(),taxProfile,eqrCompleted:false,reportSigned:false};client.tasks=generateWorkflows(client);return client}
function showNotice(message){const notice=document.getElementById("notice");notice.textContent=message;notice.classList.add("show");clearTimeout(showNotice.timer);showNotice.timer=setTimeout(()=>notice.classList.remove("show"),6000)}
function updateMetrics(){document.getElementById("clientCount").textContent=clients.length;document.getElementById("pieCount").textContent=clients.filter(requiresIeQr).length;document.getElementById("taxCount").textContent=clients.filter(client=>client.services.includes("Tax Compliance (VAT, PAYE, Income Tax)")).length}
function renderClientList(){const list=document.getElementById("clientList");if(!clients.length){list.innerHTML='<div class="empty">No client records yet. Complete the onboarding form to create the first record.</div>';updateMetrics();return}list.innerHTML=clients.slice().reverse().map(client=>{const ieqr=client.tasks.find(task=>task.id==="ieqr"),taxTaskCount=client.tasks.filter(task=>task.category==="Tax Compliance").length,servicePills=client.services.map(service=>`<span class="pill">${escapeHtml(service)}</span>`).join(""),statusPill=ieqr?`<span class="pill ${client.eqrCompleted?"":"critical"}">EQR: ${client.eqrCompleted?"Completed":"Pending Engagement Partner"}</span>`:"",auditAction=client.services.includes("Statutory Audit")?`<button data-action="sign-report" data-id="${client.id}">Mark audit report signed</button>`:"",taxPill=taxTaskCount?`<span class="pill warning">Tax tasks: ${taxTaskCount}</span>`:"";return `<article class="client-item"><div class="client-topline"><div><h3>${escapeHtml(client.companyName)}</h3><div class="client-meta">${escapeHtml(firmLabel(client.firmId))} · ${escapeHtml(client.primarySector)} · ${escapeHtml(client.branchLocation)} · ${escapeHtml(client.pipelineStage||"No pipeline stage")}</div></div><div class="client-meta">${client.engagementValue?`KES ${client.engagementValue.toLocaleString()}`:"Fee not recorded"}</div></div><div>${statusPill}${taxPill}${client.isSacco?'<span class="pill warning">SASRA annual reminder</span>':""}${client.regulators.map(item=>`<span class="pill">${escapeHtml(item)}</span>`).join("")}</div><div>${servicePills||'<span class="client-meta">No service tag selected</span>'}</div><div class="client-actions">${ieqr&&!client.eqrCompleted?`<button type="button" disabled title="Only an authenticated Engagement Partner may complete EQR">EQR completion: Engagement Partner only</button>`:""}${auditAction}<button data-action="view-tasks" data-id="${client.id}">View workflow tasks</button><button data-action="remove-client" data-id="${client.id}">Remove record</button></div></article>`}).join("");updateMetrics()}
function clientById(id){return clients.find(client=>client.id===id)}
function displayTasks(client){const taxSummary=client.taxProfile?`Tax setup: ${client.taxProfile.registrations.join(", ")||"Registrations not selected"}; report month: ${client.taxProfile.reportingMonth||"Not set"}; work packs: ${client.taxProfile.workPacks.map(id=>CRM.taxWorkPacks.find(pack=>pack.id===id)?.label||id).join(", ")}\n\n`:"";alert(`${client.companyName} workflow tasks\n\n${taxSummary}${client.tasks.map(task=>`• ${task.title} — ${task.owner} (${task.status})${task.category==="Tax Compliance"?` [Period: ${task.taxPeriod}; iTax: ${task.itaxStatus}; Review: ${task.reviewerApproval}; Posting: ${task.postingStatus}]`:""}`).join("\n")||"No workflow tasks created."}`)}
function listenForClientActions(){document.getElementById("clientList").addEventListener("click",event=>{const button=event.target.closest("button[data-action]");if(!button)return;const client=clientById(button.dataset.id);if(!client)return;if(button.dataset.action==="sign-report"){if(!client.eqrCompleted&&client.tasks.some(task=>task.id==="ieqr")){alert("Audit Report Signed is blocked until an authenticated Engagement Partner records EQR Completed.");return}client.reportSigned=true;if(!client.tasks.some(task=>task.id==="cross-sell"))client.tasks.push({id:"cross-sell",title:`On day 30 after audit completion, pitch Tax Diagnostic Reviews or Cash-flow Forecasting & Financial Modeling to ${client.companyName}`,owner:"Account Manager",status:"Scheduled"});saveClients();renderClientList();showNotice(`Audit report marked signed for ${client.companyName}; the day-30 cross-selling task has been scheduled.`)}if(button.dataset.action==="view-tasks")displayTasks(client);if(button.dataset.action==="remove-client"){if(!confirm(`Remove ${client.companyName} from this browser's CRM records?`))return;clients=clients.filter(item=>item.id!==client.id);saveClients();renderClientList();showNotice("Client record removed.")}})}

function isPotentialPie(lead){return["Financial Services","Public Sector"].includes(lead.primarySector)}
function isTaxEngagement(lead){return CRM.taxServiceNames.includes(lead?.initialService)}
function serviceLineFor(service){const group=Object.entries(CRM.serviceGroups).find(([,services])=>services.includes(service))?.[0]||"Advisory & Consulting";return{"Audit & Assurance":"Audit","Tax Services":"Tax","Accounting & Financial Reporting":"Accounting","Advisory & Consulting":"Advisory"}[group]||"Advisory"}
function specialistTeamFor(sector,serviceLine){if(sector==="Financial Services")return"Financial Services Team";if(sector==="NGO")return"NGO & Donor Team";if(sector==="Agribusiness")return"Agribusiness Team";if(sector==="Public Sector")return"Public Sector & Infrastructure Team";if(sector==="Legal")return"Legal Finance & Compliance Team";if(sector==="Education")return"Education Team";return`${serviceLine} Service Team`}
function resolveLeadRouting(lead){const serviceLine=serviceLineFor(lead.initialService);return{firmId:lead.firmId||null,branchOwner:CRM.branchRouting[lead.branchLocation]||"Practice Administration queue",serviceLine,specialistTeam:specialistTeamFor(lead.primarySector,serviceLine),routingKey:[lead.firmId||"unassigned",lead.branchLocation||"unassigned",serviceLine,lead.primarySector||"unassigned"].join(":")}}
function leadScoreFor(lead){const temperature={Cold:25,Warm:60,Hot:85}[lead.leadTemperature]||0,scopeReady=lead.scope?.yearEnd&&lead.scope?.accountingSoftware&&lead.scope?.estimatedTurnover!==null?5:0,contactReady=lead.contact?.email||lead.contact?.phone?5:0,activityReady=lead.nextActivity?.type&&lead.nextActivity?.dueDate?5:0;return Math.min(100,temperature+scopeReady+contactReady+activityReady)}
function requiresNextActivity(lead){return["Warm","Hot"].includes(lead.leadTemperature)}
function hasNextActivity(lead){return Boolean(lead.nextActivity?.type&&lead.nextActivity?.dueDate)}
function opportunityStatusFor(lead){if(lead.opportunity?.status)return lead.opportunity.status;return({"New Lead":"Lead captured","Scoping & KYC":"Qualifying","Proposal Sent":"Qualified opportunity","EL Signed":"Contract accepted","Active Engagement":"Converted to engagement","WIP / Billing":"Converted to engagement","Closed / Archived":"Closed"})[lead.stage]||"Lead captured"}
function renewalState(lead){const contract=lead.el||{},type=contract.contractType||"One-off",expiryDate=contract.expiryDate;if(!["Annual Audit","Recurring Retainer"].includes(type)||!expiryDate)return null;const today=new Date(`${operationDate()}T00:00:00Z`),expiry=new Date(`${expiryDate}T00:00:00Z`),days=Math.ceil((expiry-today)/86400000);if(days<0)return{days,label:"Contract expired",level:"critical",eligible:true};if(days<=30)return{days,label:`Renewal due in ${days} day${days===1?"":"s"}`,level:"critical",eligible:true};if(days<=60)return{days,label:`Renewal due in ${days} days`,level:"warning",eligible:true};return{days,label:`Renewal due in ${days} days`,level:"normal",eligible:false}}
function calculateProposal(proposal){const base=(Number(proposal.hours)||0)*(Number(proposal.hourlyRate)||0),discount=proposal.bundleService?base*(Number(proposal.bundleDiscount)||0)/100:0,fee=Math.max(0,base-discount),vat=fee*(Number(proposal.vatRate)||0)/100;return{base,discount,fee,vat,total:fee+vat}}
function requiresPartnerProposalApproval(lead){const threshold=lead.proposal?.partnerApprovalThreshold,proposal=calculateProposal(lead.proposal||{});return isPotentialPie(lead)||(threshold!==null&&threshold!==undefined&&threshold!==""&&proposal.total>Number(threshold))}
