function initialiseTabs(){document.querySelectorAll(".tab").forEach(tab=>tab.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(button=>button.classList.toggle("active",button===tab));document.querySelectorAll(".tab-panel").forEach(panel=>panel.classList.toggle("active",panel.id===tab.dataset.tab))}))}
function initialiseForm(){
  const form=document.getElementById("client-form");
  document.getElementById("primarySector").addEventListener("change",showRecommendation);
  document.getElementById("servicePicker").addEventListener("change",showTaxComplianceProfile);
  document.getElementById("resetForm").addEventListener("click",()=>setTimeout(()=>{showRecommendation();showTaxComplianceProfile()}));
  form.addEventListener("submit",event=>{
    event.preventDefault();if(!form.reportValidity())return;
    if(hasTaxCompliance()&&!selectedTaxWorkPacks().length){alert("Select at least one Tax Compliance Work Pack so the CRM creates the correct tasks.");return}
    const smeAuditExempt=form.elements.smeAuditExempt.checked,smeAuditExemptionBasis=form.elements.smeAuditExemptionBasis.value.trim(),sector=form.elements.primarySector.value,pie=form.elements.pieStatus.checked;
    if(smeAuditExempt&&(pie||["Financial Services","Public Sector"].includes(sector))){alert("SME Audit Exempt cannot be recorded for a PIE, Financial Services or Public Sector client. Escalate the acceptance decision to the Engagement Partner.");return}
    if(smeAuditExempt&&!smeAuditExemptionBasis){alert("Record the approved SME audit-exemption basis before enabling the optional exemption.");return}
    const client=buildClient(form);
    client.incorporationDate=form.elements.incorporationDate.value||null;
    client.smeAuditExempt=smeAuditExempt;
    client.smeAuditExemptionBasis=smeAuditExemptionBasis;
    client.etimsOnboardingRequired=form.elements.etimsOnboardingRequired.checked;
    client.tasks=generateWorkflows(client);
    const duplicate=findPotentialDuplicate(client.companyName,client.tradingName);if(duplicate&&!confirm(`Potential duplicate: ${duplicate.companyName}. Save this record anyway?`))return;
    clients.push(client);saveClients();renderClientList();form.reset();showRecommendation();showTaxComplianceProfile();showNotice(`${client.companyName} saved. ${client.tasks.length} workflow task${client.tasks.length===1?"":"s"} created.`)
  });
  document.getElementById("clearClients").addEventListener("click",()=>{if(!clients.length||!confirm("Clear every client record stored in this browser?"))return;clients=[];saveClients();renderClientList();showNotice("All local client records have been cleared.")})
}

