function latestApplicableRate(staffId,date){return staffRates.filter(rate=>rate.staffId===staffId&&rate.effectiveDate<=date&&(!rate.endDate||rate.endDate>=date)).sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate))[0]||null}
