function installPaymentMethodControl(form){if(!form||form.querySelector('[name="paymentMethod"]'))return;const reference=form.querySelector('input[name="invoicePaymentReferenceReceived"], input[name="paymentReference"]'),label=document.createElement("label");label.innerHTML='Payment method <span>*</span><select required name="paymentMethod"><option value="CASH">Cash</option><option value="MPESA">M-Pesa</option><option value="BANK_TRANSFER" selected>Bank Transfer</option><option value="CHEQUE">Cheque</option></select>';if(reference?.closest("label"))reference.closest("label").before(label);else form.querySelector(".grid")?.append(label)}
function refreshInvoiceAmounts(){const amount=Number(document.getElementById("invoiceAmount")?.value||0),vatRate=Number(document.getElementById("invoiceVatRate")?.value||0),vat=amount*vatRate/100;document.getElementById("invoiceVat").value=vat.toFixed(2);document.getElementById("invoiceTotal").value=(amount+vat).toFixed(2)}
function renderTaxInvoices(){const target=document.getElementById("taxInvoicesTable"),taxInvoices=invoices.filter(invoice=>isTaxEngagement(engagementById(invoice.engagementId))).slice().reverse();target.innerHTML=taxInvoices.length?taxInvoices.map(invoice=>{const contact=invoice.contactSnapshot||linkedContactForTaxProject(engagementById(invoice.engagementId)),status=calculatedInvoiceStatus(invoice),received=amountReceivedForInvoice(invoice),statusClass=status==="Overdue"?"overdue":status==="Reconciliation Review"?"review":status==="Partially Paid"?"partial":"";return`<tr><td><b>${escapeHtml(invoice.invoiceNumber)}</b><br><span class="hint">${escapeHtml(invoice.serviceDescription||"Tax service")}</span><br><span class="hint">${escapeHtml(invoice.taxPeriodStart||"—")} to ${escapeHtml(invoice.taxPeriodEnd||"—")}</span></td><td>${escapeHtml(engagementById(invoice.engagementId)?.companyName||"Archived client")}<br><span class="hint">${escapeHtml(contact.name||"Primary contact not recorded")}</span></td><td>${formatKes(invoiceGross(invoice))}<br><span class="hint">Received: ${formatKes(received)}</span></td><td>${escapeHtml(invoice.dueDate||"—")}<br><span class="status-pill ${statusClass}">${escapeHtml(status)}</span></td><td><span class="hint">Send through the recorded client contact channel.</span><div class="invoice-actions"><button type="button" data-invoice-action="email" data-id="${invoice.id}">Email</button><button type="button" data-invoice-action="whatsapp" data-id="${invoice.id}">WhatsApp</button></div></td></tr>`}).join(""):'<tr><td colspan="5" class="hint">No tax invoices issued. Select an active tax project, then issue an invoice or run the billing schedule.</td></tr>'}
function runTaxInvoiceSchedule(){let queued=0,skipped=0;taxProjects().forEach(engagement=>{const schedule=engagement.invoiceSchedule||{},frequency=schedule.taxBillingFrequency,months=billingMonths(frequency);if(!months||!(Number(schedule.taxBillingFee)>0)||!schedule.firstTaxInvoiceDate){skipped+=1;return}let billDate=schedule.nextInvoiceDate||schedule.firstTaxInvoiceDate,safety=0;while(billDate<=operationDate()&&safety<24){const period=taxPeriodFor(billDate,frequency),imported=invoices.some(invoice=>invoice.engagementId===engagement.id&&invoice.taxPeriodStart===period.startDate&&invoice.taxPeriodEnd===period.endDate&&invoice.sourceSystem==="ODOO");if(!imported){if(writeAlert("ODOO_INVOICE_REQUIRED",`${engagement.id}:${period.startDate}`,"Practice Administration",`Create and post the ${period.label} invoice in Odoo, then register its exact Odoo invoice number in Receivables Centre.`))queued+=1;break}billDate=addMonths(billDate,months);safety+=1}schedule.nextInvoiceDate=billDate;engagement.updatedAt=new Date().toISOString()});saveLifecycleRecords();saveOperations();renderOperations();showOperationsNotice(queued?`${queued} billing period${queued===1?" was":"s were"} queued for Odoo invoicing. The ERP will not generate a different invoice number.${skipped?` ${skipped} project(s) need billing setup.`:""}`:`No Odoo invoice imports are outstanding. ${skipped?"Complete recurring billing setup for the skipped project(s).":""}`)}
function writeAlert(alertCode,relatedRecordId,recipientPosition,detail){const today=operationDate(),exists=systemAlerts.some(alert=>alert.alertCode===alertCode&&alert.relatedRecordId===relatedRecordId&&alert.recipientPosition===recipientPosition&&alert.createdAt.slice(0,10)===today);if(exists)return false;systemAlerts.push({id:crypto.randomUUID(),alertCode,relatedRecordId,recipientPosition,detail,status:"Pending",createdAt:new Date().toISOString()});return true}
function showOperationsNotice(message,error=false){const notice=document.getElementById("operationsNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showOperationsNotice.timer);showOperationsNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function showVaultNotice(message,error=false){const notice=document.getElementById("vaultNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showVaultNotice.timer);showVaultNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function renderStaffRates(){const target=document.getElementById("staffRatesTable");target.innerHTML=staffRates.length?staffRates.slice().sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate)).map(rate=>`<tr><td>${escapeHtml(rate.staffId)}</td><td>${escapeHtml(rate.position||"Not set")}</td><td>${formatKes(rate.standardCostRate)}</td><td>${formatKes(rate.billableRate)}</td><td>${escapeHtml(rate.effectiveDate)}</td><td>${escapeHtml(rate.endDate||"Current")}</td></tr>`).join(""):'<tr><td colspan="6" class="hint">No staff rate history recorded.</td></tr>'}
function renderApprovalQueue(){const target=document.getElementById("approvalQueue"),queue=timesheets.filter(entry=>["Submitted","Approved","Rejected"].includes(entry.status)).slice().reverse();target.innerHTML=queue.length?queue.map(entry=>{const engagement=engagementById(entry.engagementId);return `<tr><td>${escapeHtml(entry.staffId)}<br><span class="hint">${escapeHtml(engagement?.companyName||"Archived engagement")}</span></td><td>${entry.hoursSpent}</td><td>${escapeHtml(entry.description)}</td><td>${escapeHtml(entry.status)}${entry.approvedBy?`<br><span class="hint">By ${escapeHtml(entry.approvedBy)}</span>`:""}</td><td>${entry.status==="Submitted"?`<button data-timesheet-action="approve" data-id="${entry.id}">Approve</button> <button data-timesheet-action="reject" data-id="${entry.id}">Reject</button>`:entry.status==="Approved"?`<button data-timesheet-action="reverse" data-id="${entry.id}">Create reversal</button>`:"—"}</td></tr>`}).join(""):'<tr><td colspan="5" class="hint">No submitted timesheets awaiting review.</td></tr>'}
function renderWipTable(){const target=document.getElementById("wipTable"),active=activeEngagements();target.innerHTML=active.length?active.map(engagement=>{const wip=wipFor(engagement),risk=wip.agreedFee&&wip.costToFee>70,loss=wip.agreedFee&&wip.actualCost>wip.agreedFee;return `<tr><td>${escapeHtml(engagementLabel(engagement))}</td><td>${wip.financial?formatKes(wip.agreedFee):"Baseline not set"}</td><td>${wip.hours.toFixed(2)}</td><td>${formatKes(wip.actualCost)}</td><td>${formatKes(wip.totalBilled)}</td><td>${formatKes(wip.unbilledWip)}</td><td class="${loss?"status-risk":risk?"status-watch":"status-ok"}">${wip.agreedFee?`${wip.costToFee.toFixed(1)}%`:"—"}</td><td class="${wip.budgetVariance>0?"status-risk":""}">${wip.financial?`${wip.budgetVariance.toFixed(2)} hrs`:"—"}</td><td>${loss?`<button data-wip-action="loss" data-id="${engagement.id}">Loss decision</button>`:`<button data-wip-action="invoice" data-id="${engagement.id}">Prepare invoice</button>`}</td></tr>`}).join(""):'<tr><td colspan="9" class="hint">Activate an engagement in the lifecycle module to begin WIP tracking.</td></tr>'}
function renderOperations(){refreshOperationalSelects();renderStaffRates();renderApprovalQueue();renderWipTable();renderTaxInvoices();renderCommunicationHub();renderDashboard()}
function recordTimesheetEntries(form){const data=new FormData(form),engagement=engagementById(data.get("timesheetEngagement")),staffId=data.get("timesheetStaffId").trim(),weekStart=data.get("timesheetWeekStart"),hours=["hoursMon","hoursTue","hoursWed","hoursThu","hoursFri","hoursSat","hoursSun"].map(name=>Number(data.get(name)||0)),total=hours.reduce((sum,value)=>sum+value,0);if(!engagement?.firmId||!data.get("timesheetTask")||!staffId||!weekStart||!total){showOperationsNotice("Select an active firm-owned engagement and task, enter a staff ID, week, description and at least one hour.",true);return}hours.forEach((hoursSpent,index)=>{if(!hoursSpent)return;timesheets.push({id:crypto.randomUUID(),staffId,position:data.get("timesheetPosition"),firmId:engagement.firmId,engagementId:engagement.id,taskId:data.get("timesheetTask"),dateLogged:addDays(weekStart,index),hoursSpent,description:data.get("timesheetDescription").trim(),status:data.get("timesheetStatus"),approvedBy:null,approvedAt:null,locked:false,entryType:"Standard",createdAt:new Date().toISOString()})});saveOperations();form.reset();document.getElementById("timesheetStatus").value="Draft";renderOperations();showOperationsNotice(`${total.toFixed(2)} hours saved as ${data.get("timesheetStatus")} for ${firmLabel(engagement.firmId)}. Submitted entries will be locked after Manager approval.`)}
