  document.getElementById("budgetedHours").addEventListener("input",event=>document.getElementById("budgetedCost").value=budgetCostFor(event.target.value)||"");document.getElementById("financialsForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),engagementId=data.get("financialEngagement"),engagement=engagementById(engagementId),cost=budgetCostFor(data.get("budgetedHours"));if(!engagement?.firmId){showOperationsNotice("Select a firm-owned active engagement before saving its WIP baseline.",true);return}if(!averageCurrentCostRate()){showOperationsNotice("Create an effective staff cost rate before calculating the engagement budgeted cost.",true);return}const record={id:financialFor(engagementId)?.id||crypto.randomUUID(),engagementId,firmId:engagement.firmId,agreedFee:Number(data.get("agreedFee")),budgetedHours:Number(data.get("budgetedHours")),budgetedCost:cost,billingStatus:data.get("billingStatus"),updatedAt:new Date().toISOString()};const index=engagementFinancials.findIndex(item=>item.engagementId===engagementId);if(index>=0)engagementFinancials[index]=record;else engagementFinancials.push(record);saveOperations();document.getElementById("budgetedCost").value=cost;renderOperations();showOperationsNotice(`Engagement financial baseline saved for ${firmLabel(engagement.firmId)} separately from the Engagement Letter record.`)});
  document.getElementById("invoiceEngagement").addEventListener("change",()=>refreshTaxInvoiceForm(true));document.getElementById("invoiceNumber").addEventListener("input",event=>{const reference=document.getElementById("invoicePaymentReference"),oldPrefix=reference.dataset.odooInvoicePrefix||"",prefix=event.target.value.trim()?`${event.target.value.trim()} — `:"";if(!reference.value||reference.value===oldPrefix||reference.value.startsWith(oldPrefix))reference.value=prefix;reference.dataset.odooInvoicePrefix=prefix});document.getElementById("invoicePaymentInvoice").addEventListener("change",event=>{const invoice=invoices.find(item=>item.id===event.target.value),reference=document.getElementById("invoicePaymentReferenceReceived");if(invoice)reference.value=`${invoice.invoiceNumber} — `});["invoiceAmount","invoiceVatRate"].forEach(id=>document.getElementById(id).addEventListener("input",refreshInvoiceAmounts));document.getElementById("invoiceForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),engagement=engagementById(data.get("invoiceEngagement")),number=data.get("invoiceNumber").trim(),paymentReference=data.get("invoicePaymentReference").trim(),periodStart=data.get("invoicePeriodStart"),periodEnd=data.get("invoicePeriodEnd"),issued=data.get("invoiceDateIssued"),due=data.get("invoiceDueDate");if(!engagement||!isTaxEngagement(engagement)){showOperationsNotice("Select an active tax project before registering an Odoo invoice.",true);return}if(!number){showOperationsNotice("Enter the posted Odoo invoice number exactly as it appears in Odoo.",true);return}if(invoices.some(invoice=>invoice.invoiceNumber===number)){showOperationsNotice("That Odoo invoice number is already registered.",true);return}if(!paymentReferenceStartsWithInvoice(number,paymentReference)){showOperationsNotice(`Payment reference must begin with the Odoo invoice number: ${number}.`,true);return}if(periodEnd<periodStart||due<issued){showOperationsNotice("The tax period and payment due date must be in chronological order.",true);return}try{const invoice=createTaxInvoice({engagement,invoiceNumber:number,serviceDescription:data.get("invoiceServiceDescription").trim(),periodStart,periodEnd,amountBilled:Number(data.get("invoiceAmount")),vatRate:Number(data.get("invoiceVatRate")||0),dateIssued:issued,dueDate:due,paymentReference,scheduled:false});saveOperations();form.reset();renderOperations();showOperationsNotice(`Odoo invoice ${invoice.invoiceNumber} registered and ready for controlled client communication.`)}catch(error){showOperationsNotice(error.message,true)}});
  document.getElementById("invoicePaymentForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),invoice=invoices.find(item=>item.id===data.get("invoicePaymentInvoice")),amount=Number(data.get("invoicePaymentAmount"));if(!invoice){showOperationsNotice("Select the tax invoice receiving the payment.",true);return}const outstanding=invoiceGross(invoice)-amountReceivedForInvoice(invoice);if(amount>outstanding+.01){showOperationsNotice(`Payment exceeds the remaining balance of ${formatKes(outstanding)}. Record an approved credit or refund separately.`,true);return}const receivedReference=data.get("invoicePaymentReferenceReceived").trim();if(!paymentReferenceStartsWithInvoice(invoice.invoiceNumber,receivedReference)){showOperationsNotice(`Payment reference must begin with the Odoo invoice number: ${invoice.invoiceNumber}.`,true);return}const matched=normaliseReference(receivedReference).includes(normaliseReference(invoice.paymentReference))||normaliseReference(receivedReference).includes(normaliseReference(invoice.invoiceNumber));invoicePayments.push({id:crypto.randomUUID(),invoiceId:invoice.id,amountReceived:amount,dateReceived:data.get("invoicePaymentDate"),paymentReference:receivedReference,paymentMethod:data.get("paymentMethod")||"BANK_TRANSFER",status:matched?"Matched":"Review",createdAt:new Date().toISOString(),sourceSystem:"ODOO"});invoice.status=calculatedInvoiceStatus(invoice);if(invoice.status==="Paid")invoice.datePaid=data.get("invoicePaymentDate");if(!matched)writeAlert("TAX_PAYMENT_REVIEW",invoice.id,"Practice Administration",`Payment reference ${receivedReference} does not match tax invoice ${invoice.invoiceNumber}; reconcile before closure.`);syncFinancialBillingStatus(invoice.engagementId);saveOperations();form.reset();renderOperations();showOperationsNotice(matched?`Payment matched to Odoo invoice ${invoice.invoiceNumber}. Status: ${invoice.status}.`:`Payment recorded for review. The reference does not match ${invoice.invoiceNumber}.`,!matched)});
  document.getElementById("approvalQueue").addEventListener("click",event=>{const button=event.target.closest("button[data-timesheet-action]");if(!button)return;const entry=timesheets.find(item=>item.id===button.dataset.id);if(!entry)return;if(button.dataset.timesheetAction==="approve"){const managerId=prompt("Enter the approving Manager staff ID.");if(!managerId)return;const rate=latestApplicableRate(entry.staffId,entry.dateLogged);if(!rate){showOperationsNotice("Approval is blocked because there is no effective staff cost rate for this timesheet date.",true);return}entry.status="Approved";entry.approvedBy=managerId;entry.approvedAt=new Date().toISOString();entry.costAtApproval=rate.standardCostRate;entry.locked=true;showOperationsNotice("Timesheet approved and locked. Any correction must use a reversal entry.")}if(button.dataset.timesheetAction==="reject"){const reason=prompt("Enter the rejection reason.");if(!reason)return;entry.status="Rejected";entry.rejectionReason=reason;showOperationsNotice("Timesheet rejected and returned for correction.")}if(button.dataset.timesheetAction==="reverse"){timesheets.push({id:crypto.randomUUID(),staffId:entry.staffId,position:entry.position,firmId:entry.firmId||engagementById(entry.engagementId)?.firmId||null,engagementId:entry.engagementId,taskId:entry.taskId,dateLogged:operationDate(),hoursSpent:-Number(entry.hoursSpent),description:`Reversal of locked entry ${entry.id}: ${entry.description}`,status:"Submitted",approvedBy:null,approvedAt:null,locked:false,entryType:"Reversal",createdAt:new Date().toISOString()});showOperationsNotice("A separate negative reversal entry has been created for Manager approval.")}saveOperations();renderOperations()});
  document.getElementById("wipTable").addEventListener("click",event=>{const button=event.target.closest("button[data-wip-action]");if(!button)return;const engagement=engagementById(button.dataset.id),financial=financialFor(button.dataset.id),wip=wipFor(engagement);if(button.dataset.wipAction==="loss"){const decision=prompt("Record the Partner decision: write off overrun or issue supplementary invoice.");if(!decision)return;financial.lossDecision=decision;financial.lossDecisionAt=new Date().toISOString();saveOperations();renderOperations();showOperationsNotice("Loss decision recorded against the engagement financials.")}else if(isTaxEngagement(engagement)){document.getElementById("invoiceEngagement").value=engagement.id;refreshTaxInvoiceForm(true);document.getElementById("invoiceAmount").value=Math.max(0,wip.agreedFee-wip.totalBilled);refreshInvoiceAmounts();showOperationsNotice("Tax invoice form prepared with the remaining agreed fee. Confirm the period and amount before issuing.")}else showOperationsNotice("The invoice workspace is deliberately restricted to tax projects. Use the finance system for non-tax engagement invoices.",true)});
  document.getElementById("taxInvoicesTable").addEventListener("click",event=>{const button=event.target.closest("button[data-invoice-action]");if(!button)return;const invoice=invoices.find(item=>item.id===button.dataset.id);if(!invoice)return;const contact=invoice.contactSnapshot||linkedContactForTaxProject(engagementById(invoice.engagementId)),message=`Tax invoice ${invoice.invoiceNumber} for ${formatKes(invoiceGross(invoice))} is due on ${invoice.dueDate}. Payment reference: ${invoice.paymentReference}.`;if(button.dataset.invoiceAction==="email"){if(!contact.email){showOperationsNotice("No primary-contact email is recorded for this tax invoice.",true);return}recordInvoiceCommunication(invoice,"EMAIL",contact.email,message);saveOperations();renderCommunicationHub();window.location.href=`mailto:${encodeURIComponent(contact.email)}?subject=${encodeURIComponent(`Tax invoice ${invoice.invoiceNumber}`)}&body=${encodeURIComponent(message)}`;showOperationsNotice("Invoice email composition opened and the communication was logged.")}if(button.dataset.invoiceAction==="whatsapp"){const recipient=whatsappRecipient(contact.phone);if(!recipient){showOperationsNotice("No primary-contact phone is recorded for this tax invoice.",true);return}recordInvoiceCommunication(invoice,"WHATSAPP",contact.phone,message);saveOperations();renderCommunicationHub();window.open(`https://wa.me/${recipient}?text=${encodeURIComponent(message)}`,"_blank","noopener");showOperationsNotice("WhatsApp invoice message opened and the communication was logged.")}});
  document.getElementById("runTaxInvoiceSchedule").addEventListener("click",runTaxInvoiceSchedule);document.getElementById("runOperationsControls").addEventListener("click",()=>{runFirmPulseControls();saveOperations();renderOperations();showOperationsNotice("WIP, billing and loss controls have been scanned.")});renderOperations()
