const auditPlanningAreas=["Overall audit strategy and plan","Client acceptance and continuance","Time budgets","Materiality","Analytical review","Understanding the entity and environment","Internal controls","Risk assessment and response","Fraud risk","Brought-forward points","Permanent-file review"];
const requiredAuditPlanningAreas=["Overall audit strategy and plan","Client acceptance and continuance","Materiality","Risk assessment and response","Fraud risk"];
const auditWorkpaperAreas=["Intangible Assets","Property, Plant & Equipment","Inventories","Trade & Other Receivables","Cash & Bank Balances","Related Party Disclosures","Trade & Other Payables","Borrowings","Current Tax","Deferred Tax","Capital & Reserves","Commitments & Contingencies","Directors' Emoluments & Transactions","Cash Flow Statement","Income","Expenditure"];
const auditControlAreas=[...auditWorkpaperAreas,"General ledger and financial statements","Regulatory compliance and governance","IT controls and system-generated information","Payroll and statutory deductions"];
const auditCompletionTypes=["Overall audit conclusion","Calling-over checklist","Partner review","Team debrief","Senior attention points","Client meeting agenda","Unadjusted errors","Carry-forward points","Subsequent events","Going concern","Draft financial statements","Management letter","Signed representation letter","Management letter cover letter"];
const requiredAuditCompletionTypes=["Overall audit conclusion","Calling-over checklist","Partner review","Subsequent events","Going concern","Signed representation letter"];
function isAuditEngagement(engagement){return Boolean(engagement&&engagement.initialService==="Statutory Audit"&&["Active Engagement","WIP / Billing"].includes(engagement.stage))}
function auditFileById(id){return auditFiles.find(file=>file.id===id)}
function auditFileEngagement(file){return engagementById(file?.engagementId)}
function auditFileLabel(file){const engagement=auditFileEngagement(file);return `${engagement?.companyName||"Archived client"} — YE ${file.reportingYearEnd}`}
function auditTbForFile(auditFileId){return auditTrialBalances.find(record=>record.auditFileId===auditFileId)}
function auditTbLinesForFile(auditFileId){return auditTbLines.filter(line=>line.auditFileId===auditFileId)}
function auditPlanningForFile(auditFileId){return auditPlanningControls.filter(record=>record.auditFileId===auditFileId)}
function auditWorkpapersForFile(auditFileId){return auditWorkpapers.filter(record=>record.auditFileId===auditFileId)}
function auditCompletionForFile(auditFileId){return auditCompletionItems.filter(record=>record.auditFileId===auditFileId)}
function auditAttachmentsForFile(auditFileId){return auditFileAttachments.filter(record=>record.auditFileId===auditFileId)}
function auditPopulationById(id){return auditPopulationControls.find(record=>record.id===id)}
function auditPopulationsForFile(auditFileId){return auditPopulationControls.filter(record=>record.auditFileId===auditFileId)}
function auditReconciliationsForFile(auditFileId){return auditReconciliations.filter(record=>record.auditFileId===auditFileId)}
function auditSamplesForFile(auditFileId){return auditSamples.filter(record=>record.auditFileId===auditFileId)}
function auditExceptionsForFile(auditFileId){return auditExceptions.filter(record=>record.auditFileId===auditFileId)}
function auditPopulationIsControlled(population){return Boolean(population&&population.status==="Controlled"&&Number(population.rowCount)>0&&population.parameters&&population.generatedAt&&population.generatedBy&&population.tbGlReference&&population.period&&population.vaultReference&&population.controlTotal!==null&&population.controlTotal!==undefined)}
function auditReconciliationIsCleared(reconciliation){return Boolean(reconciliation&&reconciliation.status==="Cleared"&&Math.abs(Number(reconciliation.difference||0))<.01&&reconciliation.clearanceReference&&reconciliation.preparedBy&&reconciliation.reviewedBy)}
function auditPopulationHasClearedReconciliation(auditFileId,populationId){return auditReconciliations.some(record=>record.auditFileId===auditFileId&&record.populationId===populationId&&auditReconciliationIsCleared(record))}
function auditSampleExceptionIsResolved(file,sample){return auditExceptionsForFile(file.id).some(exception=>exception.relatedReference===sample.reference&&["Cleared","Adjusted","Reported as unadjusted"].includes(exception.status))}
function auditFieldworkReadiness(file){const populations=auditPopulationsForFile(file.id),samples=auditSamplesForFile(file.id),exceptions=auditExceptionsForFile(file.id),uncontrolled=populations.filter(population=>!auditPopulationIsControlled(population)),unreconciled=populations.filter(population=>!auditPopulationHasClearedReconciliation(file.id,population.id)),provisional=samples.filter(sample=>sample.stage==="Provisional"),sampleExceptions=samples.filter(sample=>sample.stage==="Exception"&&!auditSampleExceptionIsResolved(file,sample)),unresolved=exceptions.filter(exception=>exception.status==="Open");return{populations,uncontrolled,unreconciled,provisional,sampleExceptions,unresolved,hasControlledSource:populations.some(auditPopulationIsControlled),ready:Boolean(populations.length)&&!uncontrolled.length&&!unreconciled.length&&!provisional.length&&!sampleExceptions.length&&!unresolved.length}}
function auditItemIsComplete(item){return["Complete","Reviewed"].includes(item?.status)}
function auditEqrReady(file){const engagement=auditFileEngagement(file);return !engagement?.potentialPie||!engagement.workflowTasks?.some(task=>task.id==="audit-eqr"&&task.status!=="Completed")}
function auditReadiness(file){const planning=auditPlanningForFile(file.id),tb=auditTbForFile(file.id),lines=auditTbLinesForFile(file.id),workpapers=auditWorkpapersForFile(file.id),completion=auditCompletionForFile(file.id),fieldwork=auditFieldworkReadiness(file),planningMissing=requiredAuditPlanningAreas.filter(area=>!auditItemIsComplete(planning.find(item=>item.area===area))),completionMissing=requiredAuditCompletionTypes.filter(type=>!auditItemIsComplete(completion.find(item=>item.type===type))),tbBalanced=Boolean(tb?.isBalanced),tbMapped=Boolean(lines.length)&&lines.every(line=>Boolean(line.auditArea)),hasPreparedWorkpaper=workpapers.some(item=>["Prepared","Reviewed"].includes(item.status)),eqrReady=auditEqrReady(file);return{planningMissing,completionMissing,tbBalanced,tbMapped,hasPreparedWorkpaper,eqrReady,fieldwork,planningReady:!planningMissing.length,tbReady:tbBalanced&&tbMapped,completionReady:!completionMissing.length,closureReady:!planningMissing.length&&tbBalanced&&tbMapped&&hasPreparedWorkpaper&&fieldwork.ready&&!completionMissing.length&&eqrReady}}
