function runAuditFieldworkControls(){auditFiles.forEach(file=>{if(file.status==="Archived")return;const fieldwork=auditFieldworkReadiness(file);if(!fieldwork.populations.length)writeAlert("AUDIT_SOURCE_POPULATION_GATE",file.id,"Audit Supervisor",`Audit file ${auditFileLabel(file)} has no controlled source population.`);if(fieldwork.uncontrolled.length)writeAlert("AUDIT_SOURCE_CONTROL_GATE",file.id,"Audit Supervisor",`Audit file ${auditFileLabel(file)} has ${fieldwork.uncontrolled.length} source population(s) missing control evidence.`);if(fieldwork.unreconciled.length)writeAlert("AUDIT_RECONCILIATION_GATE",file.id,"Manager",`Audit file ${auditFileLabel(file)} has ${fieldwork.unreconciled.length} source population(s) without a cleared TB / GL reconciliation.`);if(fieldwork.provisional.length)writeAlert("AUDIT_SAMPLE_FINALISATION_GATE",file.id,"Audit Supervisor",`Audit file ${auditFileLabel(file)} has ${fieldwork.provisional.length} provisional sample(s) awaiting finalisation.`);if(fieldwork.sampleExceptions.length)writeAlert("AUDIT_SAMPLE_EXCEPTION_GATE",file.id,"Manager",`Audit file ${auditFileLabel(file)} has ${fieldwork.sampleExceptions.length} sample exception(s) needing a resolved or reported exception record.`);if(fieldwork.unresolved.length)writeAlert("AUDIT_EXCEPTION_GATE",file.id,"Manager",`Audit file ${auditFileLabel(file)} has ${fieldwork.unresolved.length} open exception(s) or adjustment(s).`)});saveOperations();renderAudit();renderDashboard()}
