function runFirmPulseControls(){activeEngagements().forEach(engagement=>{const wip=wipFor(engagement),renewal=renewalState(engagement),renewalOwner=engagement.opportunity?.owner||engagement.routing?.branchOwner||"Account Manager";if(engagement.potentialPie&&engagement.workflowTasks?.some(task=>task.id==="audit-eqr"&&task.status!=="Completed"))writeAlert("EQR_PENDING",engagement.id,"Engagement Partner",`Potential PIE quality review remains pending for ${engagement.companyName}.`);if(wip.agreedFee&&wip.costToFee>70)writeAlert("WIP_AT_RISK",engagement.id,"Engagement Partner",`Cost is ${wip.costToFee.toFixed(1)}% of agreed fee for ${engagement.companyName}.`);if(wip.agreedFee&&wip.actualCost>wip.agreedFee)writeAlert("WIP_AT_LOSS",engagement.id,"Engagement Partner",`${engagement.companyName} has actual cost above agreed fee. Record write-off or supplementary-invoice decision.`);if(engagement.stage==="WIP / Billing"&&wip.agreedFee&&wip.totalBilled===0)writeAlert("BILLING_PENDING",engagement.id,"Practice Administration",`${engagement.companyName} is in WIP / Billing with no recorded invoice.`);if(renewal&&renewal.days<=30)writeAlert("CONTRACT_RENEWAL_30",engagement.id,renewalOwner,`${engagement.companyName}: ${renewal.label}. Start a separate renewal opportunity and refresh acceptance controls.`);else if(renewal&&renewal.days<=60)writeAlert("CONTRACT_RENEWAL_60",engagement.id,renewalOwner,`${engagement.companyName}: ${renewal.label}. Plan the EL renewal and KYC refresh.`)});lifecycleRecords.filter(lead=>["New Lead","Scoping & KYC","Proposal Sent","EL Signed"].includes(lead.stage)&&requiresNextActivity(lead)).forEach(lead=>{const owner=lead.opportunity?.owner||lead.routing?.branchOwner||"Account Manager";if(!hasNextActivity(lead))writeAlert("OPPORTUNITY_NEXT_ACTIVITY_MISSING",lead.id,owner,`${lead.companyName} is ${lead.leadTemperature} but has no controlled next activity.`);else if(lead.nextActivity.dueDate<=operationDate())writeAlert("OPPORTUNITY_FOLLOW_UP_DUE",lead.id,owner,`${lead.companyName}: ${lead.nextActivity.type} is due or overdue.`)});documentLogs.filter(log=>log.actionType.includes("BLOCKED")).forEach(log=>writeAlert("DOCUMENT_LOCK_BREACH",log.documentId,"Engagement Partner",`Locked-document event for ${log.documentName}.`));runHrComplianceControls();runAttendanceControls()}
