function refreshHelpdeskSelects(){setSelectItems("ticketEngagement",activeEngagements(),"No engagement link");const target=document.getElementById("commentTicket"),previous=target.value;target.innerHTML=`<option value="">Select ticket…</option>${tickets.slice().reverse().map(ticket=>`<option value="${ticket.id}">${escapeHtml(ticket.ticketNumber)} — ${escapeHtml(ticket.subject)}</option>`).join("")}`;if([...target.options].some(option=>option.value===previous))target.value=previous}
