// Production-readiness layer. The browser build demonstrates the same archival,
// traceability and restricted-portal controls that the PostgreSQL migration enforces.
const readinessStorage={changeLog:"pcl-crm-system-change-log-v1",archivedRecords:"pcl-crm-archived-records-v1",portalAccounts:"pcl-crm-client-portal-accounts-v1"};
let systemChangeLog=loadRecords(readinessStorage.changeLog),archivedRecords=loadRecords(readinessStorage.archivedRecords),clientPortalAccounts=loadRecords(readinessStorage.portalAccounts);
function saveReadinessRecords(){localStorage.setItem(readinessStorage.changeLog,JSON.stringify(systemChangeLog));localStorage.setItem(readinessStorage.archivedRecords,JSON.stringify(archivedRecords));localStorage.setItem(readinessStorage.portalAccounts,JSON.stringify(clientPortalAccounts))}
function readinessActor(){return document.getElementById("governanceActor")?.value.trim()||"System Administrator (prototype)"}
function recordSystemChange({recordType,recordId,action,beforeValue=null,afterValue=null,firmId=null,reason=""}){systemChangeLog.push({id:crypto.randomUUID(),recordType,recordId:String(recordId),action,beforeValue,afterValue,firmId,reason,actor:readinessActor(),changedAt:new Date().toISOString(),correlationId:crypto.randomUUID()});saveReadinessRecords()}
function showReadinessNotice(message,error=false){const notice=document.getElementById("readinessNotice");if(!notice)return;notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showReadinessNotice.timer);showReadinessNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function activeClientRecords(){return clients.filter(client=>!client.deletedAt)}
function updateMetrics(){const active=activeClientRecords();document.getElementById("clientCount").textContent=active.length;document.getElementById("pieCount").textContent=active.filter(requiresIeQr).length;document.getElementById("taxCount").textContent=active.filter(client=>client.services.includes("Tax Compliance (VAT, PAYE, Income Tax)")).length}
function renderClientList(){const list=document.getElementById("clientList"),active=activeClientRecords();if(!active.length){list.innerHTML='<div class="empty">No active client records. Archived records remain retained in the governance register.</div>';updateMetrics();return}list.innerHTML=active.slice().reverse().map(client=>{const ieqr=client.tasks.find(task=>task.id==="ieqr"),taxTaskCount=client.tasks.filter(task=>task.category==="Tax Compliance").length,servicePills=client.services.map(service=>`<span class="pill">${escapeHtml(service)}</span>`).join(""),statusPill=ieqr?`<span class="pill ${client.eqrCompleted?"":"critical"}">EQR: ${client.eqrCompleted?"Completed":"Pending Engagement Partner"}</span>`:"",auditAction=client.services.includes("Statutory Audit")?`<button data-action="sign-report" data-id="${client.id}">Mark audit report signed</button>`:"",taxPill=taxTaskCount?`<span class="pill warning">Tax tasks: ${taxTaskCount}</span>`:"";return `<article class="client-item"><div class="client-topline"><div><h3>${escapeHtml(client.companyName)}</h3><div class="client-meta">${escapeHtml(firmLabel(client.firmId))} · ${escapeHtml(client.primarySector)} · ${escapeHtml(client.branchLocation)} · ${escapeHtml(client.pipelineStage||"No pipeline stage")}</div></div><div class="client-meta">${client.engagementValue?`KES ${client.engagementValue.toLocaleString()}`:"Fee not recorded"}</div></div><div>${statusPill}${taxPill}${client.isSacco?'<span class="pill warning">SASRA annual reminder</span>':""}${client.regulators.map(item=>`<span class="pill">${escapeHtml(item)}</span>`).join("")}</div><div>${servicePills||'<span class="client-meta">No service tag selected</span>'}</div><div class="client-actions">${ieqr&&!client.eqrCompleted?'<button type="button" disabled title="Only an authenticated Engagement Partner may complete EQR">EQR completion: Engagement Partner only</button>':""}${auditAction}<button data-action="view-tasks" data-id="${client.id}">View workflow tasks</button><button data-action="archive-client" data-id="${client.id}">Archive record</button></div></article>`}).join("");updateMetrics()}
function archiveClientRecord(client,reason){if(!client||client.deletedAt)return;const beforeValue={...client};client.deletedAt=new Date().toISOString();client.deletedBy=readinessActor();client.deleteReason=reason;archivedRecords.push({id:crypto.randomUUID(),recordType:"Client",recordId:client.id,archivedAt:client.deletedAt,archivedBy:client.deletedBy,reason,recordSnapshot:beforeValue});recordSystemChange({recordType:"Client",recordId:client.id,action:"SOFT_DELETE",beforeValue,afterValue:{...client},firmId:client.firmId,reason});saveClients();saveReadinessRecords();renderClientList();renderProductionReadiness();showNotice(`${client.companyName} archived. Its retained record and change trail remain available to authorised users.`)}
function archivedDocumentRecord(record,reason){const snapshot={...record};archivedRecords.push({id:crypto.randomUUID(),recordType:"Document",recordId:record.id,archivedAt:new Date().toISOString(),archivedBy:readinessActor(),reason,recordSnapshot:snapshot});recordSystemChange({recordType:"Document",recordId:record.id,action:"SOFT_DELETE",beforeValue:snapshot,afterValue:{...snapshot,deletedAt:new Date().toISOString()},firmId:record.firmId,reason});documents=documents.filter(item=>item.id!==record.id);saveOperations();saveReadinessRecords();renderVault();renderProductionReadiness()}
function portalEngagements(){return activeEngagements().filter(engagement=>engagement.firmId)}
function clientVisibleProjectStatus(engagement){return({"Active Engagement":"Work in progress","WIP / Billing":"Completion and billing in progress","Closed / Archived":"Completed"})[engagement?.stage]||"Engagement setup in progress"}
function portalAccountById(id){return clientPortalAccounts.find(account=>account.id===id)}
function injectProductionReadiness(){const nav=document.querySelector(".tabs"),shell=document.querySelector(".shell"),tab=document.createElement("button"),section=document.createElement("section");tab.className="tab";tab.type="button";tab.dataset.tab="production-readiness";tab.textContent="Go-live controls";nav.append(tab);section.id="production-readiness";section.className="tab-panel";section.innerHTML=`<div class="intro"><div><h2>Production readiness and client portal</h2><p>Controls here retain local prototype evidence. In production, PostgreSQL migrations, authenticated APIs, object storage, RLS and scheduled workers enforce these rules.</p></div></div><div class="notice" id="readinessNotice" role="status"></div><div class="metric-grid"><div class="card metric-card"><b id="readinessActiveClients">0</b><span>Active client records</span></div><div class="card metric-card"><b id="readinessArchived">0</b><span>Archived records retained</span></div><div class="card metric-card"><b id="readinessChanges">0</b><span>Recorded control changes</span></div><div class="card metric-card"><b id="readinessPortalAccounts">0</b><span>Restricted portal accounts</span></div></div><div class="operations-layout"><div><form id="governanceForm" class="card form-card"><div class="section-heading"><h3>Governance action context</h3><span class="hint">Production obtains this from the authenticated session</span></div><div class="grid"><label class="full">Authenticated staff ID / position<input required id="governanceActor" name="governanceActor" placeholder="e.g. Engagement Partner or staff ID" /></label><label class="full">Reason for archival or exception<input id="governanceReason" name="governanceReason" placeholder="Required before a production archive or override" /></label></div><div class="actions"><button class="btn secondary" type="button" id="runReadinessChecks">Run controlled UAT checks</button></div></form><div class="card side-card" style="margin-top:18px"><div class="section-heading"><h3>Go-live release gates</h3><span class="hint">All items must be evidenced before launch</span></div><div id="readinessChecklist" class="workflow"></div></div></div><div><form id="portalInviteForm" class="card form-card"><div class="section-heading"><h3>Restricted client portal invitation</h3><span class="hint">Creates access only to the selected engagement's client view</span></div><div class="grid"><label class="full">Engagement <span>*</span><select required id="portalInviteEngagement" name="portalInviteEngagement"></select></label><label>Client contact name <span>*</span><input required id="portalInviteName" name="portalInviteName" /></label><label>Client contact email <span>*</span><input required type="email" id="portalInviteEmail" name="portalInviteEmail" /></label><label class="checkbox-line full"><input checked type="checkbox" id="portalInviteMfa" name="portalInviteMfa" />Require multi-factor authentication at activation</label></div><div class="actions"><button class="btn primary" type="submit">Create portal invitation</button></div></form><div class="card side-card" style="margin-top:18px"><div class="section-heading"><h3>Portal-safe client preview</h3><span class="hint">No internal notes, staff, workpapers or WIP are exposed</span></div><label>Portal account<select id="portalPreviewAccount"></select></label><div id="portalPreview" class="workflow" style="margin-top:16px"></div></div></div></div><div class="section"><div class="section-heading"><h3>System change and archive register</h3><span class="hint">Append-only production audit record, browser preview below</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Record</th><th>Action</th><th>Actor</th><th>Reason</th></tr></thead><tbody id="readinessChangeLog"></tbody></table></div></div>`;shell.append(section);tab.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(button=>button.classList.toggle("active",button===tab));document.querySelectorAll(".tab-panel").forEach(panel=>panel.classList.toggle("active",panel===section));renderProductionReadiness()})}
function setPortalEngagementOptions(){const target=document.getElementById("portalInviteEngagement");if(!target)return;const prior=target.value,items=portalEngagements();target.innerHTML=`<option value="">Select active engagement…</option>${items.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(engagementLabel(item))}</option>`).join("")}`;if(items.some(item=>item.id===prior))target.value=prior}
function renderPortalPreview(){const select=document.getElementById("portalPreviewAccount"),target=document.getElementById("portalPreview");if(!select||!target)return;const current=select.value;select.innerHTML=`<option value="">Select a portal account…</option>${clientPortalAccounts.filter(account=>account.status!=="Revoked").map(account=>`<option value="${escapeHtml(account.id)}">${escapeHtml(account.contactName)} — ${escapeHtml(account.clientName)}</option>`).join("")}`;if(clientPortalAccounts.some(account=>account.id===current))select.value=current;const account=portalAccountById(select.value);if(!account){target.innerHTML="<p>Select an invited portal account to confirm the restricted client view.</p>";return}const engagement=engagementById(account.engagementId),invoiceRows=invoices.filter(invoice=>invoice.engagementId===account.engagementId&&!invoice.deletedAt),pbcRows=pbcRequests.filter(request=>request.engagementId===account.engagementId),reports=documents.filter(documentRecord=>documentRecord.engagementId===account.engagementId&&documentRecord.isLocked&&documentRecord.category==="final-reports"&&!documentRecord.deletedAt);target.innerHTML=`<h3>${escapeHtml(account.clientName)}</h3><p><b>Visible project status:</b> ${escapeHtml(clientVisibleProjectStatus(engagement))}</p><p><b>Invoices:</b> ${invoiceRows.length?invoiceRows.map(invoice=>`${escapeHtml(invoice.invoiceNumber)} (${escapeHtml(invoice.status)})`).join(", "):"No client-visible invoice"}</p><p><b>PBC requests:</b> ${pbcRows.length?`${pbcRows.length} pending or completed request(s)`:"No request"}</p><p><b>Released final reports:</b> ${reports.length?reports.map(report=>escapeHtml(report.fileName)).join(", "):"None released"}</p><p class="hint">MFA required: ${account.mfaRequired?"Yes":"No"}. This preview deliberately excludes internal communications, audit workpapers, client lists, staff allocation and WIP.</p>`}
function renderProductionReadiness(){const active=activeClientRecords(),portalCount=clientPortalAccounts.filter(account=>account.status!=="Revoked").length;const setText=(id,value)=>{const element=document.getElementById(id);if(element)element.textContent=value};setText("readinessActiveClients",active.length);setText("readinessArchived",archivedRecords.length);setText("readinessChanges",systemChangeLog.length);setText("readinessPortalAccounts",portalCount);setPortalEngagementOptions();const checklist=document.getElementById("readinessChecklist");if(checklist)checklist.innerHTML=`<h3>Required production evidence</h3><p>1. Controlled migration applied, including soft delete, change log, service catalogue, RLS, privacy and portal tables.</p><p>2. API activation uses one idempotent database transaction and an outbox, not browser-only writes.</p><p>3. RLS is tested for firm and branch access, including direct API calls.</p><p>4. Backup restore, privacy-incident and data-subject-request procedures are evidenced.</p><p>5. Intern, PIE gate, scheduler and concurrent-use UAT scripts pass in a sandbox.</p>`;const target=document.getElementById("readinessChangeLog");if(target)target.innerHTML=systemChangeLog.length?systemChangeLog.slice().reverse().slice(0,30).map(entry=>`<tr><td>${escapeHtml(entry.changedAt.replace("T"," ").slice(0,19))}</td><td>${escapeHtml(entry.recordType)} · ${escapeHtml(entry.recordId)}</td><td>${escapeHtml(entry.action)}</td><td>${escapeHtml(entry.actor)}</td><td>${escapeHtml(entry.reason||"—")}</td></tr>`).join(""):'<tr><td colspan="5" class="hint">No local governance actions recorded.</td></tr>';renderPortalPreview()}
function runReadinessChecks(){const tests=[{name:"Intern fee exposure",result:"Pass by design",detail:"Production RLS/API must omit financial fields for Intern, Assistant and Supervisor profiles."},{name:"PIE completion gate",result:"Pass by design",detail:"Partner Review remains blocked while the EQR task is pending."},{name:"Archival preservation",result:"Pass",detail:"Browser archive retains a snapshot and an append-only change record."},{name:"Cross-firm integrity",result:"Pass by design",detail:"Lead and engagement firm ownership remains immutable."},{name:"Scheduler / restore",result:"Evidence required",detail:"Run the worker and restore tests in the deployed sandbox before go-live."}];showReadinessNotice(tests.map(test=>`${test.name}: ${test.result} — ${test.detail}`).join(" "))}
function initialiseProductionReadiness(){injectProductionReadiness();document.getElementById("clientList").addEventListener("click",event=>{const button=event.target.closest("button[data-action='archive-client']");if(!button)return;const client=clientById(button.dataset.id),reason=document.getElementById("governanceReason")?.value.trim()||prompt("Enter the archival reason.");if(!reason){showReadinessNotice("An archival reason is required.",true);return}archiveClientRecord(client,reason)});document.addEventListener("click",event=>{const clearButton=event.target.closest("#clearClients"),deleteButton=event.target.closest("button[data-document-action='delete']");if(clearButton){event.preventDefault();event.stopImmediatePropagation();showReadinessNotice("Bulk deletion is disabled. Archive individual records with a reason so the audit trail is retained.",true);return}if(!deleteButton)return;event.preventDefault();event.stopImmediatePropagation();const record=documents.find(item=>item.id===deleteButton.dataset.id),reason=document.getElementById("governanceReason")?.value.trim()||prompt("Enter the document archival reason.");if(!record||!reason){showReadinessNotice("A document archive requires a reason.",true);return}archivedDocumentRecord(record,reason);showReadinessNotice(`${record.fileName} archived with its retained metadata snapshot.`)},true);document.getElementById("portalInviteEngagement").addEventListener("change",event=>{const engagement=engagementById(event.target.value);if(!engagement)return;document.getElementById("portalInviteName").value=engagement.contact?.name||"";document.getElementById("portalInviteEmail").value=engagement.contact?.email||""});document.getElementById("portalInviteForm").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),engagement=engagementById(data.get("portalInviteEngagement"));if(!engagement){showReadinessNotice("Select an active firm-owned engagement before inviting a client.",true);return}const email=data.get("portalInviteEmail").trim().toLowerCase();if(clientPortalAccounts.some(account=>account.engagementId===engagement.id&&account.email===email&&account.status!=="Revoked")){showReadinessNotice("This contact already has a portal invitation for the selected engagement.",true);return}const account={id:crypto.randomUUID(),engagementId:engagement.id,firmId:engagement.firmId,clientName:engagement.companyName,contactName:data.get("portalInviteName").trim(),email,status:"Invited",mfaRequired:data.get("portalInviteMfa")==="on",invitedAt:new Date().toISOString(),invitedBy:readinessActor()};clientPortalAccounts.push(account);recordSystemChange({recordType:"Client portal account",recordId:account.id,action:"INSERT",afterValue:account,firmId:account.firmId,reason:"Restricted client portal invitation created"});saveReadinessRecords();event.currentTarget.reset();renderProductionReadiness();showReadinessNotice(`Portal invitation created for ${account.contactName}. Production issues a time-limited activation link and requires MFA.`)});document.getElementById("portalPreviewAccount").addEventListener("change",renderPortalPreview);document.getElementById("runReadinessChecks").addEventListener("click",runReadinessChecks);renderProductionReadiness()}
