// Engagement channels and virtual meetings. This browser implementation is a
// controlled interface prototype. Production creates Jitsi rooms and signed
// join URLs server-side; neither meeting credentials nor recordings are stored
// in browser storage.
const meetingWorkspaceStorage={channels:"pcl-crm-engagement-channels-v1",messages:"pcl-crm-channel-messages-v1",appointments:"pcl-crm-channel-appointments-v1",sessions:"pcl-crm-meeting-sessions-v1",settings:"pcl-crm-meeting-settings-v1"};
let engagementChannels=loadRecords(meetingWorkspaceStorage.channels),channelMessages=loadRecords(meetingWorkspaceStorage.messages),channelAppointments=loadRecords(meetingWorkspaceStorage.appointments),meetingSessions=loadRecords(meetingWorkspaceStorage.sessions),meetingServiceSettings=loadRecords(meetingWorkspaceStorage.settings)[0]||{provider:"GOOGLE_MEET",serviceUrl:"https://meet.google.com"};
const meetingHostPositions=["Engagement Partner","Audit Manager","Audit Supervisor"];
const channelTypes=["Engagement","Fieldwork Team","Manager Review","Partner Review","Tax Compliance"];
function saveMeetingWorkspace(){localStorage.setItem(meetingWorkspaceStorage.channels,JSON.stringify(engagementChannels));localStorage.setItem(meetingWorkspaceStorage.messages,JSON.stringify(channelMessages));localStorage.setItem(meetingWorkspaceStorage.appointments,JSON.stringify(channelAppointments));localStorage.setItem(meetingWorkspaceStorage.sessions,JSON.stringify(meetingSessions));localStorage.setItem(meetingWorkspaceStorage.settings,JSON.stringify([meetingServiceSettings]))}
function channelById(id){return engagementChannels.find(channel=>channel.id===id)}
function channelAppointmentsFor(channelId){return channelAppointments.filter(appointment=>appointment.channelId===channelId)}
function channelSessionsFor(channelId){return meetingSessions.filter(session=>session.channelId===channelId)}
function channelMessagesFor(channelId){return channelMessages.filter(message=>message.channelId===channelId).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt))}
function meetingServiceUrl(){return String(meetingServiceSettings.serviceUrl||"").trim().replace(/\/+$/,"")}
function meetingRoomUrl(session){return `${meetingServiceUrl()}/${encodeURIComponent(session.roomSlug)}`}
function meetingStatusClass(status){return String(status||"").toLowerCase()}
function channelMeetingStatus(channel){return channelSessionsFor(channel.id).find(session=>session.status==="LIVE")||channelSessionsFor(channel.id).filter(session=>session.status==="SCHEDULED").sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))[0]||null}
function ensureChannelChain(channel){const engagement=engagementById(channel?.engagementId);return Boolean(channel&&engagement&&channel.firmId===engagement.firmId)}
function channelLabel(channel){const engagement=engagementById(channel?.engagementId);return `${engagement?.companyName||"Unknown engagement"} — ${channel?.name||"Untitled channel"}`}
function showMeetingNotice(message,error=false){const notice=document.getElementById("meetingNotice");if(!notice)return;notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showMeetingNotice.timer);showMeetingNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
