// Phase 1 uses Google Meet. The persistence model remains provider-neutral so
// a later Jitsi, Teams or Zoom integration does not change engagement history.
function googleMeetUrl(value){const parsed=new URL(String(value||"").trim());if(parsed.protocol!=="https:"||parsed.hostname.toLowerCase()!=="meet.google.com")throw new Error("Use the secure Google Meet link created in Google Calendar, for example https://meet.google.com/abc-defg-hij.");return parsed.toString()}
function googleMeetingExternalId(url){return new URL(url).pathname.replace(/^\/+|\/+$/g,"")}
function decorateGoogleMeetWorkspace(){const section=document.getElementById("meetings");if(!section)return;const intro=section.querySelector(".intro p"),introText="Private audit-team channels, Google Meet scheduling and controlled meeting minutes. Every channel inherits its engagement’s handling firm; a different firm requires a separate engagement.";if(intro&&intro.textContent!==introText)intro.textContent=introText;const scheduledLabel=section.querySelector(".metric-card:nth-child(2) span");if(scheduledLabel&&scheduledLabel.textContent!=="Google Meet meetings scheduled")scheduledLabel.textContent="Google Meet meetings scheduled";section.querySelectorAll("#meetingChannelConsole [data-meeting-action='join']").forEach(button=>{const session=meetingSessions.find(item=>item.id===button.dataset.id);if(session?.provider==="GOOGLE_MEET"){button.dataset.meetingAction="join-google";button.textContent="Join Google Meet"}})}
function scheduleGoogleMeet(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),channel=channelById(data.get("channelId")),startsAt=data.get("startsAt"),endsAt=data.get("endsAt");try{if(!ensureChannelChain(channel))throw new Error("Select an engagement channel with the matching locked handling firm.");if(!meetingHostPositions.includes(data.get("hostPosition")))throw new Error("Only an Engagement Partner, Audit Manager or Audit Supervisor can host a meeting.");if(!startsAt||!endsAt||new Date(endsAt)<=new Date(startsAt))throw new Error("The meeting end time must be after its start time.");const joinUrl=googleMeetUrl(data.get("joinUrl")),externalMeetingId=googleMeetingExternalId(joinUrl),appointment={id:crypto.randomUUID(),channelId:channel.id,engagementId:channel.engagementId,firmId:channel.firmId,provider:"GOOGLE_MEET",joinUrl,externalMeetingId,title:data.get("title").trim(),startsAt:new Date(startsAt).toISOString(),endsAt:new Date(endsAt).toISOString(),attendees:data.get("attendees").trim(),status:"SCHEDULED",createdAt:new Date().toISOString()};channelAppointments.push(appointment);const session=createMeetingSession(channel,{title:appointment.title,startsAt:appointment.startsAt,endsAt:appointment.endsAt,hostPosition:data.get("hostPosition"),appointmentId:appointment.id,meetingProvider:"GOOGLE_MEET",joinUrl,externalMeetingId});appointment.meetingSessionId=session.id;writeChannelMessage(channel.id,`Google Meet scheduled: ${session.title}. The external meeting link is retained with the controlled appointment and is not posted in the channel.`,data.get("hostPosition"),"MEETING",session.id);saveMeetingWorkspace();form.reset();renderMeetingWorkspace();decorateGoogleMeetWorkspace();showMeetingNotice("Google Meet appointment saved. The link remains separate from invoices and QR communications.")}catch(error){showMeetingNotice(error.message,true)}}
function configureGoogleMeetPhaseOne(){meetingServiceSettings={...meetingServiceSettings,provider:"GOOGLE_MEET",serviceUrl:"https://meet.google.com"};saveMeetingWorkspace();const section=document.getElementById("meetings"),oldForm=document.getElementById("meetingAppointmentForm"),oldSettings=document.getElementById("meetingSettingsForm");if(!section||!oldForm)return;const form=document.createElement("form");form.id="meetingAppointmentForm";form.className="card form-card compact-card";form.innerHTML=`<div class="section-heading"><h3>Schedule Google Meet</h3><span class="hint">Phase 1, provider can change later</span></div><div class="grid"><label class="full">Engagement channel <span>*</span><select required id="meetingAppointmentChannel" name="channelId"></select></label><label class="full">Meeting title <span>*</span><input required name="title" placeholder="e.g. Audit planning meeting" /></label><label class="full">Google Meet link <span>*</span><input required type="url" name="joinUrl" placeholder="https://meet.google.com/abc-defg-hij" /><small class="hint">Create this in Google Calendar first, then paste the secure link here.</small></label><label>Starts <span>*</span><input required type="datetime-local" name="startsAt" /></label><label>Ends <span>*</span><input required type="datetime-local" name="endsAt" /></label><label>Host position <span>*</span><select name="hostPosition">${meetingHostPositions.map(position=>`<option>${position}</option>`).join("")}</select></label><label>Attendee notes<input name="attendees" placeholder="Positions or controlled invite list" /></label></div><div class="actions"><button class="btn primary" type="submit">Save Google Meet appointment</button></div></form>`;oldForm.replaceWith(form);form.addEventListener("submit",scheduleGoogleMeet);if(oldSettings){const settings=document.createElement("div");settings.id="meetingSettingsForm";settings.className="meeting-config";settings.innerHTML="<b>Phase 1 provider: Google Meet.</b> Create the meeting in Google Calendar, then add its link to the controlled appointment. The link is not an invoice QR and meeting minutes still return to the Communication Hub. Jitsi, Teams or Zoom can be enabled later without changing the engagement record.";oldSettings.replaceWith(settings)}const console=document.getElementById("meetingChannelConsole");console?.addEventListener("click",event=>{const button=event.target.closest("button[data-meeting-action='join-google']");if(!button)return;event.preventDefault();const session=meetingSessions.find(item=>item.id===button.dataset.id);if(!session||!ensureChannelChain(channelById(session.channelId))){showMeetingNotice("Meeting firm and engagement control failed.",true);return}if(!session.joinUrl){showMeetingNotice("This Google Meet appointment does not have a retained meeting link.",true);return}window.open(session.joinUrl,"_blank","noopener,noreferrer")});const observer=new MutationObserver(()=>queueMicrotask(decorateGoogleMeetWorkspace));observer.observe(section,{childList:true,subtree:true,attributes:true,attributeFilter:["data-meeting-action"]});renderMeetingWorkspace();decorateGoogleMeetWorkspace()}
configureGoogleMeetPhaseOne();
document.addEventListener("submit",event=>{const form=event.target.closest?.("#channelMessageForm");if(!form||form.hidden)return;event.preventDefault();const data=new FormData(form),channel=channelById(data.get("channelId"));if(!ensureChannelChain(channel)){showMeetingNotice("The selected channel fails the engagement-firm control.",true);return}writeChannelMessage(channel.id,data.get("message").trim(),data.get("authorPosition"));saveMeetingWorkspace();renderMeetingWorkspace();showMeetingNotice("Internal channel update posted.")});
function runReadinessChecks(){const tests=[{name:"Intern fee exposure",result:"Sandbox evidence required",detail:"Confirm API and database policy deny fees, rates, WIP, export, approval and report sign-off."},{name:"PIE completion gate",result:"Sandbox evidence required",detail:"Attempt Partner completion while an EQR task is pending and confirm a hard block."},{name:"Archival preservation",result:"Preview passed",detail:"The browser archive retains a snapshot and append-only local change record; confirm the PostgreSQL trigger in the deployment."},{name:"Cross-firm and cross-branch access",result:"Sandbox evidence required",detail:"Use direct API calls with each role, firm and branch profile."},{name:"Scheduler, recovery and concurrent use",result:"Sandbox evidence required",detail:"Evidence the scheduled alert, restore and agreed peak-load tests before go-live."}];showReadinessNotice(tests.map(test=>`${test.name}: ${test.result} — ${test.detail}`).join(" "))}

// Client statutory-compliance controls. The production scheduler is defined in
// database_schema.sql; the browser preview surfaces the same scheduled tasks.
function clientProfileForLead(lead){return clients.find(client=>client.firmId===lead?.firmId&&normaliseName(client.companyName)===normaliseName(lead?.companyName)&&!client.deletedAt)}
function smeAuditExemptForLead(lead){return Boolean(lead?.smeAuditExempt||clientProfileForLead(lead)?.smeAuditExempt)}
function refreshStatutoryTaskState(client){let changed=false;(client.tasks||[]).filter(task=>task.category==="Statutory Compliance"&&task.activateOn&&task.status==="Scheduled"&&operationDate()>=task.activateOn).forEach(task=>{task.status="Open";changed=true});return changed}
function renderClientList(){
  const list=document.getElementById("clientList"),active=activeClientRecords();
  active.forEach(refreshStatutoryTaskState);
  if(!active.length){list.innerHTML='<div class="empty">No active client records. Archived records remain retained in the governance register.</div>';updateMetrics();return}
  list.innerHTML=active.slice().reverse().map(client=>{
    const tasks=client.tasks||[],ieqr=tasks.find(task=>task.id==="ieqr"),taxTaskCount=tasks.filter(task=>task.category==="Tax Compliance").length,brsTask=tasks.find(task=>task.templateCode==="BRS_ANNUAL_RETURN_FILING"),etimsTask=tasks.find(task=>task.templateCode==="ETIMS_ONBOARDING"),servicePills=(client.services||[]).map(service=>`<span class="pill">${escapeHtml(service)}</span>`).join(""),statusPill=ieqr?`<span class="pill ${client.eqrCompleted?"":"critical"}">EQR: ${client.eqrCompleted?"Completed":"Pending Engagement Partner"}</span>`:"",auditAction=(client.services||[]).includes("Statutory Audit")&&!client.smeAuditExempt?`<button data-action="sign-report" data-id="${client.id}">Mark audit report signed</button>`:"",taxPill=taxTaskCount?`<span class="pill warning">Tax tasks: ${taxTaskCount}</span>`:"",exemptionPill=client.smeAuditExempt?'<span class="pill warning">SME audit exemption active</span>':"",brsPill=brsTask?`<span class="pill ${brsTask.status==="Open"?"warning":""}">BRS annual return: ${escapeHtml(brsTask.status)} · ${escapeHtml(brsTask.dueDate)}</span>`:"",etimsPill=etimsTask?`<span class="pill warning">eTIMS onboarding: ${escapeHtml(etimsTask.status)}</span>`:"";
    return `<article class="client-item"><div class="client-topline"><div><h3>${escapeHtml(client.companyName)}</h3><div class="client-meta">${escapeHtml(firmLabel(client.firmId))} · ${escapeHtml(client.primarySector)} · ${escapeHtml(client.branchLocation)} · ${escapeHtml(client.pipelineStage||"No pipeline stage")}</div></div><div class="client-meta">${client.engagementValue?`KES ${client.engagementValue.toLocaleString()}`:"Fee not recorded"}</div></div><div>${statusPill}${taxPill}${exemptionPill}${brsPill}${etimsPill}${client.isSacco?'<span class="pill warning">SASRA annual reminder</span>':""}${(client.regulators||[]).map(item=>`<span class="pill">${escapeHtml(item)}</span>`).join("")}</div><div>${servicePills||'<span class="client-meta">No service tag selected</span>'}</div><div class="client-actions">${ieqr&&!client.eqrCompleted?'<button type="button" disabled title="Only an authenticated Engagement Partner may complete EQR">EQR completion: Engagement Partner only</button>':""}${auditAction}<button data-action="view-tasks" data-id="${client.id}">View workflow tasks</button><button data-action="archive-client" data-id="${client.id}">Archive record</button></div></article>`
  }).join("");
  saveClients();updateMetrics()
}
function displayTasks(client){const statutory=(client.tasks||[]).filter(task=>task.category==="Statutory Compliance").map(task=>`• ${task.title} — ${task.owner} (${task.status})${task.dueDate?` [Due: ${task.dueDate}; activates: ${task.activateOn}]`:""}${task.evidenceRule?`\n  Evidence: ${task.evidenceRule}`:""}`).join("\n"),taxSummary=client.taxProfile?`Tax setup: ${client.taxProfile.registrations.join(", ")||"Registrations not selected"}; report month: ${client.taxProfile.reportingMonth||"Not set"}; work packs: ${client.taxProfile.workPacks.map(id=>CRM.taxWorkPacks.find(pack=>pack.id===id)?.label||id).join(", ")}\n\n`:"";alert(`${client.companyName} workflow tasks\n\n${client.smeAuditExempt?"SME audit exemption is active. The statutory-audit workflow is not available unless the exemption is removed.\n\n":""}${taxSummary}${statutory?`Statutory compliance\n${statutory}\n\n`:""}${(client.tasks||[]).filter(task=>task.category!=="Statutory Compliance").map(task=>`• ${task.title} — ${task.owner} (${task.status})${task.category==="Tax Compliance"?` [Period: ${task.taxPeriod}; iTax: ${task.itaxStatus}; Review: ${task.reviewerApproval}; Posting: ${task.postingStatus}]`:""}`).join("\n")||"No workflow tasks created."}`)}
document.getElementById("clientList")?.addEventListener("click",event=>{const button=event.target.closest("button[data-action='sign-report']"),client=clientById(button?.dataset.id);if(button&&client?.smeAuditExempt){event.preventDefault();event.stopImmediatePropagation();alert("Audit sign-off is unavailable while SME Audit Exempt is active. Remove the exemption through the controlled acceptance process before creating an audit workflow.")}},true);

// Recurring Task Engine V2. The browser preview follows the Kenya business
// calendar; production must execute the matching database functions through a
// server scheduler in Africa/Nairobi rather than rely on an open browser.
const recurringTaskPreviewStorage="pcl-crm-recurring-task-runs-v2";
let recurringTaskRuns=loadRecords(recurringTaskPreviewStorage);
const recurringTaskTemplates={
  WEEKLY_TAX_HEALTH_CHECK:{title:"Weekly Tax Health Check",owner:"Tax Assistant",escalation:"Tax Supervisor",frequency:"Weekly"},
  START_PAYROLL_PROCESSING:{title:"Start Payroll Processing",owner:"Tax Assistant",escalation:"Tax Manager",frequency:"Monthly"},
  FILE_PAYE_RETURN:{title:"File PAYE Return",owner:"Tax Assistant",escalation:"Tax Manager",frequency:"Monthly",critical:true},
  FILE_VAT_TOT_RETURN:{title:"File VAT / TOT Return",owner:"Tax Assistant",escalation:"Tax Manager",frequency:"Monthly",critical:true},
  PREPARE_ANNUAL_INCOME_TAX:{title:"Prepare Annual Income Tax",owner:"Tax Assistant",escalation:"Engagement Partner",frequency:"Annual"},
  VERIFY_ETIMS_COMPLIANCE:{title:"Verify eTIMS Compliance",owner:"Tax Assistant",escalation:"Tax Manager",frequency:"Quarterly"}
};
function saveRecurringTaskRuns(){localStorage.setItem(recurringTaskPreviewStorage,JSON.stringify(recurringTaskRuns));saveLifecycleRecords();saveClients();saveOperations()}
function previewDate(value){const source=value instanceof Date?value:new Date(`${value||operationDate()}T00:00:00Z`);return new Date(Date.UTC(source.getUTCFullYear(),source.getUTCMonth(),source.getUTCDate()))}
function previewDateKey(value){return previewDate(value).toISOString().slice(0,10)}
function previewAddDays(value,days){const date=previewDate(value);date.setUTCDate(date.getUTCDate()+days);return date}
function previewMonthEnd(value){const date=previewDate(value);return new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0))}
function previewDueAt(value){return `${previewDateKey(value)}T23:59:00+03:00`}
function previewWeekStart(value){const date=previewDate(value);date.setUTCDate(date.getUTCDate()-((date.getUTCDay()+6)%7));return date}
function recurringTaxEngagements(){return activeEngagements().filter(engagement=>isTaxEngagement(engagement)||Boolean(clientProfileForLead(engagement)?.taxProfile))}
function recurringTaskRows(){return activeEngagements().flatMap(engagement=>(engagement.workflowTasks||[]).filter(task=>task.isRecurring).map(task=>({engagement,task}))).sort((a,b)=>String(a.task.dueAt||a.task.dueDate).localeCompare(String(b.task.dueAt||b.task.dueDate)))}
function taskIsComplete(task){return ["Completed","Submitted"].includes(task.status)}
function createRecurringPreviewTask(engagement,code,periodStart,periodEnd,dueDate,triggerDate){const template=recurringTaskTemplates[code],periodKey=previewDateKey(periodStart),existing=(engagement.workflowTasks||[]).find(task=>task.isRecurring&&task.recurrenceCode===code&&task.recurrencePeriodStart===periodKey);if(existing)return false;const groupId=`${engagement.firmId}:${code}:${periodKey}`,task={id:`recurring-${code.toLowerCase()}-${periodKey}-${crypto.randomUUID().slice(0,8)}`,title:template.title,owner:template.owner,status:"Pending",category:"Tax Compliance",isRecurring:true,recurrenceCode:code,recurrenceGroupId:groupId,recurrencePeriodStart:periodKey,recurrencePeriodEnd:previewDateKey(periodEnd),triggerDate:previewDateKey(triggerDate),dueDate:previewDateKey(dueDate),dueAt:previewDueAt(dueDate),isOverdue:false,overdueAt:null,escalationOwner:template.escalation,critical:Boolean(template.critical)};engagement.workflowTasks=engagement.workflowTasks||[];engagement.workflowTasks.push(task);if(!recurringTaskRuns.some(run=>run.groupId===groupId))recurringTaskRuns.push({groupId,firmId:engagement.firmId,taskCode:code,periodStart:periodKey,periodEnd:previewDateKey(periodEnd),dueAt:task.dueAt,triggeredAt:new Date().toISOString()});return true}
function findAnnualTaxDueDate(engagement){const profile=clientProfileForLead(engagement)?.taxProfile,yearEnd=profile?.financialYearEnd;if(!yearEnd)return null;const result=previewDate(yearEnd);result.setUTCMonth(result.getUTCMonth()+6);return result}
function raiseRecurringAlert(code,task,engagement,position,detail){writeAlert(code,task.id,position,`${engagement.companyName}: ${detail}`)}
function markRecurringOverdues(runDate){const today=previewDate(runDate);let count=0;recurringTaskRows().forEach(({engagement,task})=>{if(taskIsComplete(task)||task.isOverdue||previewDate(task.dueDate)>=today)return;task.isOverdue=true;task.overdueAt=new Date().toISOString();task.status=task.status==="Pending"?"Pending":"In Progress";count+=1;if(task.recurrenceCode==="WEEKLY_TAX_HEALTH_CHECK"){raiseRecurringAlert("WEEKLY_TAX_TASK_OVERDUE",task,engagement,"Tax Assistant",`the ${task.recurrencePeriodStart}–${task.recurrencePeriodEnd} weekly tax check is overdue.`);raiseRecurringAlert("WEEKLY_TAX_TASK_OVERDUE",task,engagement,"Tax Supervisor",`the ${task.recurrencePeriodStart}–${task.recurrencePeriodEnd} weekly tax check is overdue.`)}else if(task.recurrenceCode==="FILE_PAYE_RETURN")raiseRecurringAlert("PAYE_CRITICAL_OVERDUE",task,engagement,"Tax Manager",`PAYE return was not submitted by ${task.dueDate}; KRA deadline reference is the 9th.`);else if(task.recurrenceCode==="FILE_VAT_TOT_RETURN")raiseRecurringAlert("VAT_TOT_CRITICAL_OVERDUE",task,engagement,"Tax Manager",`VAT / TOT return was not submitted by ${task.dueDate}; KRA deadline reference is the 20th.`);else if(task.recurrenceCode==="VERIFY_ETIMS_COMPLIANCE"){const client=clientProfileForLead(engagement);if(client?.taxProfile){client.taxProfile.taxAtRisk=true;client.taxProfile.etimsStatus="Tax At Risk"}raiseRecurringAlert("ETIMS_TAX_AT_RISK",task,engagement,"Tax Manager","quarterly eTIMS verification is incomplete or non-compliant; the client profile is marked Tax At Risk.")}});return count}
function runRecurringTaskEngine(runDate=operationDate()){const today=previewDate(runDate),day=today.getUTCDate(),dayOfWeek=today.getUTCDay(),weekStart=previewWeekStart(today),weekEnd=previewAddDays(weekStart,6),monthEnd=previewMonthEnd(today);let created=0,overdue=0;const taxEngagements=recurringTaxEngagements(),createFor=(code,start,end,due)=>taxEngagements.forEach(engagement=>{if(createRecurringPreviewTask(engagement,code,start,end,due,today))created+=1});if(dayOfWeek===1)createFor("WEEKLY_TAX_HEALTH_CHECK",weekStart,weekEnd,weekEnd);if(day===22)createFor("START_PAYROLL_PROCESSING",new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),1)),monthEnd,new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),25)));if(day===6)createFor("FILE_PAYE_RETURN",new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),1)),monthEnd,new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),7)));if(day===15)createFor("FILE_VAT_TOT_RETURN",new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),1)),monthEnd,new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),18)));if([0,3,6,9].includes(today.getUTCMonth())&&day===1)createFor("VERIFY_ETIMS_COMPLIANCE",today,previewAddDays(today,14),previewAddDays(today,14));taxEngagements.forEach(engagement=>{const due=findAnnualTaxDueDate(engagement);if(due){const trigger=previewDate(due);trigger.setUTCMonth(trigger.getUTCMonth()-2);if(previewDateKey(trigger)===previewDateKey(today)&&createRecurringPreviewTask(engagement,"PREPARE_ANNUAL_INCOME_TAX",today,due,due,today))created+=1}});overdue=markRecurringOverdues(today);recurringTaskRows().forEach(({engagement,task})=>{if(task.recurrenceCode==="START_PAYROLL_PROCESSING"&&day>=23&&task.recurrencePeriodStart.slice(0,7)===previewDateKey(today).slice(0,7)&&task.status==="Pending")raiseRecurringAlert("PAYROLL_NOT_STARTED",task,engagement,"Tax Manager",`monthly payroll processing has not started by the 23rd.`);if(task.recurrenceCode==="PREPARE_ANNUAL_INCOME_TAX"&&!taskIsComplete(task)){const oneMonthBefore=previewDate(task.dueDate);oneMonthBefore.setUTCMonth(oneMonthBefore.getUTCMonth()-1);if(previewDateKey(today)>=previewDateKey(oneMonthBefore))raiseRecurringAlert("ANNUAL_TAX_PARTNER_ESCALATION",task,engagement,"Engagement Partner",`annual income tax preparation has not started one month before ${task.dueDate}.`)}});saveRecurringTaskRuns();return{created,overdue}}
function injectRecurringTaskEngine(){if(document.getElementById("recurring-task-engine"))return;const nav=document.querySelector(".tabs"),shell=document.querySelector(".shell"),tab=document.createElement("button"),section=document.createElement("section"),before=nav.querySelector("[data-tab='production-readiness']");tab.className="tab";tab.type="button";tab.dataset.tab="recurring-task-engine";tab.innerHTML='<svg class="nav-icon" aria-hidden="true"><use href="#icon-calendar" /></svg>Recurring tasks';section.id="recurring-task-engine";section.className="tab-panel";section.innerHTML=`<div class="intro"><div><h2>Recurring Tax Task Engine</h2><p>Kenya business-time controls for weekly, monthly, quarterly and annual tax work. The browser view demonstrates the rules; production executes the same runs at 00:01 / 00:05 Africa/Nairobi through the scheduler.</p></div></div><div class="notice" id="recurringTaskNotice" role="status"></div><div class="metric-grid"><div class="card metric-card"><b id="recurringTaskOpen">0</b><span>Open recurring tasks</span></div><div class="card metric-card"><b id="recurringTaskOverdue">0</b><span>Red overdue tasks</span></div><div class="card metric-card"><b id="recurringTaskWeekly">0</b><span>Current weekly sprint</span></div><div class="card metric-card"><b id="recurringTaskRisk">0</b><span>Tax-at-risk client profiles</span></div></div><div class="operations-layout"><form id="recurringTaskRunForm" class="card form-card"><div class="section-heading"><h3>Scheduler preview</h3><span class="hint">Use the task date in Kenya time</span></div><div class="grid"><label>Run date <span>*</span><input required type="date" name="runDate" id="recurringTaskRunDate" /></label><div class="full hint">Monday 00:01 creates the weekly sprint. Monday 00:05 marks the prior open sprint red and alerts the Tax Assistant and Tax Supervisor. Daily checks handle monthly and annual deadlines.</div></div><div class="actions"><button class="btn primary" type="submit">Run scheduled actions</button></div></form><div class="card side-card"><div class="section-heading"><h3>Task matrix V2</h3><span class="hint">Configured policy</span></div><div class="recurring-matrix"><p><b>Weekly tax health:</b> Monday → Sunday 23:59.</p><p><b>PAYE:</b> create 6th; due 7th; critical control before the 9th.</p><p><b>VAT / TOT:</b> create 15th; due 18th; critical control before the 20th.</p><p><b>Annual income tax:</b> create two months before its tax deadline.</p><p><b>eTIMS:</b> quarterly on 1 Jan/Apr/Jul/Oct; due 15th.</p></div></div></div><div class="section"><div class="section-heading"><h3>Generated recurring tasks</h3><span class="hint">A red border and warning mark work past its deadline</span></div><div id="recurringTaskList" class="recurring-task-list"></div></div>`;if(before)nav.insertBefore(tab,before);else nav.append(tab);shell.append(section);tab.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(button=>button.classList.toggle("active",button===tab));document.querySelectorAll(".tab-panel").forEach(panel=>panel.classList.toggle("active",panel===section));renderRecurringTaskEngine()});document.getElementById("recurringTaskRunForm").addEventListener("submit",event=>{event.preventDefault();const result=runRecurringTaskEngine(new FormData(event.currentTarget).get("runDate"));showRecurringTaskNotice(`${result.created} task(s) generated; ${result.overdue} task(s) marked overdue.`);renderRecurringTaskEngine();renderDashboard()});document.getElementById("recurringTaskList").addEventListener("click",event=>{const button=event.target.closest("button[data-recurring-action]"),row=recurringTaskRows().find(item=>item.task.id===button?.dataset.id);if(!row)return;if(button.dataset.recurringAction==="complete"){row.task.status="Completed";row.task.isOverdue=false;row.task.completedAt=new Date().toISOString();if(row.task.recurrenceCode==="VERIFY_ETIMS_COMPLIANCE"){const client=clientProfileForLead(row.engagement);if(client?.taxProfile){client.taxProfile.taxAtRisk=false;if(client.taxProfile.etimsStatus==="Tax At Risk")client.taxProfile.etimsStatus="Verified"}}showRecurringTaskNotice(`${row.task.title} marked completed.`)}if(button.dataset.recurringAction==="noncompliant"&&row.task.recurrenceCode==="VERIFY_ETIMS_COMPLIANCE"){row.task.status="Non-compliant";row.task.isOverdue=true;const client=clientProfileForLead(row.engagement);if(client?.taxProfile){client.taxProfile.taxAtRisk=true;client.taxProfile.etimsStatus="Tax At Risk"}raiseRecurringAlert("ETIMS_TAX_AT_RISK",row.task,row.engagement,"Tax Manager","eTIMS verification is marked non-compliant.");showRecurringTaskNotice(`${row.engagement.companyName} is now Tax At Risk.`,true)}saveRecurringTaskRuns();renderRecurringTaskEngine();renderDashboard()});renderRecurringTaskEngine()}
function showRecurringTaskNotice(message,error=false){const target=document.getElementById("recurringTaskNotice");if(!target)return;target.textContent=message;target.classList.add("show");target.style.background=error?"#fbe8e8":"";target.style.color=error?"#8b2828":"";clearTimeout(showRecurringTaskNotice.timer);showRecurringTaskNotice.timer=setTimeout(()=>target.classList.remove("show"),7000)}
function renderRecurringTaskEngine(){const section=document.getElementById("recurring-task-engine");if(!section)return;const rows=recurringTaskRows(),today=operationDate(),setText=(id,value)=>{const node=document.getElementById(id);if(node)node.textContent=value};setText("recurringTaskOpen",rows.filter(row=>!taskIsComplete(row.task)).length);setText("recurringTaskOverdue",rows.filter(row=>row.task.isOverdue).length);setText("recurringTaskWeekly",rows.filter(row=>row.task.recurrenceCode==="WEEKLY_TAX_HEALTH_CHECK"&&row.task.recurrencePeriodStart===previewDateKey(previewWeekStart(today))).length);setText("recurringTaskRisk",clients.filter(client=>client.taxProfile?.taxAtRisk).length);const input=document.getElementById("recurringTaskRunDate");if(input&&!input.value)input.value=today;const target=document.getElementById("recurringTaskList");target.innerHTML=rows.length?rows.map(({engagement,task})=>`<article class="recurring-task-card ${task.isOverdue?"overdue":""}"><div><h4>${task.isOverdue?"⚠ ":""}${escapeHtml(task.title)}</h4><p>${escapeHtml(engagement.companyName)} · ${escapeHtml(firmLabel(engagement.firmId))}</p><p class="hint">${escapeHtml(task.recurrenceCode)} · Sprint / period: ${escapeHtml(task.recurrencePeriodStart)} → ${escapeHtml(task.recurrencePeriodEnd)} · Due ${escapeHtml(task.dueDate)} 23:59</p></div><div><span class="pill ${task.isOverdue?"critical":task.status==="Completed"?"":"warning"}">${escapeHtml(task.isOverdue?"OVERDUE":task.status)}</span><p class="hint">Owner: ${escapeHtml(task.owner)} · Escalates to ${escapeHtml(task.escalationOwner)}</p><div class="client-actions">${!taskIsComplete(task)?`<button data-recurring-action="complete" data-id="${task.id}">Mark complete</button>`:""}${task.recurrenceCode==="VERIFY_ETIMS_COMPLIANCE"&&!taskIsComplete(task)?`<button data-recurring-action="noncompliant" data-id="${task.id}">Mark non-compliant</button>`:""}</div></div></article>`).join(""):'<div class="empty">No recurring tasks generated yet. Run a scheduled date or activate a Tax engagement.</div>'}
document.head.insertAdjacentHTML("beforeend",`<style>.recurring-task-list{display:grid;gap:12px}.recurring-task-card{background:#fff;border:1px solid #dfe8e3;border-left:5px solid #2d7558;border-radius:10px;padding:16px;display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.recurring-task-card.overdue{border-color:#cb4040;border-left-color:#cb4040;background:#fff8f8}.recurring-task-card h4{margin:0 0 6px}.recurring-task-card p{margin:4px 0}.recurring-matrix p{margin:7px 0}@media(max-width:700px){.recurring-task-card{display:block}}</style>`);
injectRecurringTaskEngine();

// Discuss / channel enhancements. These add Odoo-style conversation modes,
// role policies, auto-subscription and controlled #channel cross-posting while
// retaining the existing engagement-firm lock and Google Meet configuration.
const discussStorage={policies:"pcl-crm-channel-policies-v2",memberships:"pcl-crm-channel-memberships-v2",crossPosts:"pcl-crm-channel-cross-posts-v2"};
let channelPolicies=loadRecords(discussStorage.policies),channelMemberships=loadRecords(discussStorage.memberships),channelCrossPosts=loadRecords(discussStorage.crossPosts);
function saveDiscussControls(){localStorage.setItem(discussStorage.policies,JSON.stringify(channelPolicies));localStorage.setItem(discussStorage.memberships,JSON.stringify(channelMemberships));localStorage.setItem(discussStorage.crossPosts,JSON.stringify(channelCrossPosts));saveMeetingWorkspace()}
function channelSlug(name){return String(name||"").toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")}
function channelPolicy(channel){let policy=channelPolicies.find(item=>item.channelId===channel?.id);if(!policy&&channel){policy={channelId:channel.id,conversationType:channel.conversationType||"GROUP",description:channel.description||"Engagement collaboration channel",authorizedPositions:String(channel.memberPositions||"Engagement Partner, Audit Manager, Audit Supervisor, Audit Assistant").split(",").map(item=>item.trim()).filter(Boolean),autoSubscribePositions:["Engagement Partner","Audit Manager","Audit Supervisor","Audit Assistant"],updatedAt:new Date().toISOString()};channelPolicies.push(policy)}return policy}
function syncDiscussChannels(){let changed=false;activeEngagements().forEach(engagement=>{let channel=engagementChannels.find(item=>item.engagementId===engagement.id&&item.channelType==="Engagement");if(!channel){channel={id:crypto.randomUUID(),engagementId:engagement.id,firmId:engagement.firmId,name:"Engagement team",channelType:"Engagement",conversationType:"GROUP",visibility:"Engagement team",parentChannelId:null,memberPositions:"Engagement Partner, Audit Manager, Audit Supervisor, Audit Assistant",description:`Primary collaboration channel for ${engagement.companyName}.`,createdAt:new Date().toISOString(),createdByPosition:"System"};engagementChannels.push(channel);writeChannelMessage(channel.id,`Engagement channel created automatically for ${engagement.companyName}. Assigned audit roles are subscribed.`,"System","SYSTEM");changed=true}const policy=channelPolicy(channel);policy.autoSubscribePositions.forEach(position=>{if(!channelMemberships.some(member=>member.channelId===channel.id&&member.position===position&&member.active!==false)){channelMemberships.push({id:crypto.randomUUID(),channelId:channel.id,position,source:"ENGAGEMENT_ASSIGNMENT",active:true,createdAt:new Date().toISOString()});changed=true}})});if(changed)saveDiscussControls()}
function allowedChannelPosition(channel,position){const policy=channelPolicy(channel);if(policy.conversationType==="CHANNEL")return true;return policy.authorizedPositions.includes(position)||channelMemberships.some(member=>member.channelId===channel.id&&member.position===position&&member.active!==false)}
function crossPostChannelMentions(body,{engagementId,firmId,sourceChannelId=null,sourceCommunicationId=null,authorPosition="System"}={}){const mentions=String(body||"").match(/#[a-z0-9][a-z0-9-]*/gi)||[];if(!mentions.length)return;const source=sourceChannelId?channelById(sourceChannelId):null;mentions.forEach(mention=>{const target=engagementChannels.find(channel=>channel.engagementId===engagementId&&channel.firmId===firmId&&channelSlug(channel.name)===mention.slice(1).toLowerCase());if(!target||target.id===source?.id||!allowedChannelPosition(target,authorPosition))return;const crossPostKey=`${sourceCommunicationId||sourceChannelId}:${target.id}:${mention}`;if(channelCrossPosts.some(item=>item.key===crossPostKey))return;const context=source?`Cross-post from #${channelSlug(source.name)}`:"Cross-post from Communication Hub";const message={id:crypto.randomUUID(),channelId:target.id,body:`${context}: ${String(body).replace(mention,"").trim()}`,authorPosition,messageType:"CROSS_POST",sourceCommunicationId,createdAt:new Date().toISOString()};channelMessages.push(message);channelCrossPosts.push({key:crossPostKey,sourceCommunicationId,sourceChannelId,targetChannelId:target.id,createdAt:new Date().toISOString()})});saveDiscussControls()}
const baseChannelMessageWriter=writeChannelMessage;
writeChannelMessage=function(channelId,body,authorPosition="System",messageType="MESSAGE",meetingSessionId=null){baseChannelMessageWriter(channelId,body,authorPosition,messageType,meetingSessionId);const source=channelById(channelId);if(source&&messageType!=="CROSS_POST")crossPostChannelMentions(body,{engagementId:source.engagementId,firmId:source.firmId,sourceChannelId:source.id,authorPosition})};
const baseCommunicationLogger=logCommunication;
logCommunication=function(payload){const record=baseCommunicationLogger(payload);if(record.engagementId&&record.direction!=="OUTBOUND")crossPostChannelMentions(record.body,{engagementId:record.engagementId,firmId:record.firmId,sourceCommunicationId:record.id,authorPosition:record.staffId||"System"});return record};
function renderDiscussPolicyPanel(){const panel=document.getElementById("discussPolicyPanel");if(!panel)return;syncDiscussChannels();const select=document.getElementById("discussPolicyChannel"),prior=select?.value||"",channels=engagementChannels.filter(ensureChannelChain);select.innerHTML=`<option value="">Select a controlled channel…</option>${channels.map(channel=>`<option value="${channel.id}">${escapeHtml(channelLabel(channel))}</option>`).join("")}`;if(channels.some(channel=>channel.id===prior))select.value=prior;const selected=channelById(select.value)||channels[0],policy=channelPolicy(selected);if(selected&&select)select.value=selected.id;document.getElementById("discussConversationType").value=policy?.conversationType||"GROUP";document.getElementById("discussAuthorizedPositions").value=(policy?.authorizedPositions||[]).join(", ");document.getElementById("discussAutoPositions").value=(policy?.autoSubscribePositions||[]).join(", ");document.getElementById("discussChannelDescription").value=policy?.description||"";const memberTarget=document.getElementById("discussMemberList");memberTarget.innerHTML=selected?`<p><b>${policy.conversationType==="CHANNEL"?"#":"🔒"} ${escapeHtml(selected.name)}</b> · ${escapeHtml(policy.conversationType==="CHANNEL"?"Public channel":"Restricted conversation")}</p><p class="hint">Auto-subscribed: ${(channelMemberships.filter(member=>member.channelId===selected.id&&member.active!==false).map(member=>member.position).join(", ")||"None")}. Live updates in production use WebSocket / SSE after the API confirms channel membership.</p>`:'<p class="hint">Create or select an active engagement channel first.</p>'}
function injectDiscussPolicyPanel(){const section=document.getElementById("meetings");if(!section||document.getElementById("discussPolicyPanel"))return;const panel=document.createElement("div");panel.id="discussPolicyPanel";panel.className="card form-card";panel.style.marginTop="18px";panel.innerHTML=`<div class="section-heading"><h3>Discuss access &amp; live-channel policy</h3><span class="hint">Roles/positions only — no invoice QR data</span></div><form id="discussPolicyForm" class="grid"><label class="full">Channel <select required id="discussPolicyChannel" name="channelId"></select></label><label>Conversation type <select id="discussConversationType" name="conversationType"><option value="CHANNEL"># Public channel</option><option value="GROUP">🔒 Private group</option><option value="CHAT">Direct chat</option></select></label><label>Channel description<input id="discussChannelDescription" name="description" placeholder="Purpose shown in the channel header" /></label><label class="full">Authorized positions <input id="discussAuthorizedPositions" name="authorizedPositions" placeholder="Audit Manager, Audit Supervisor" /></label><label class="full">Auto-subscribe positions <input id="discussAutoPositions" name="autoSubscribePositions" placeholder="Audit Assistant, Audit Supervisor" /></label><div class="actions full"><button class="btn secondary" type="submit">Save access policy</button></div></form><div id="discussMemberList" class="meeting-config"></div>`;section.append(panel);document.getElementById("discussPolicyChannel").addEventListener("change",renderDiscussPolicyPanel);document.getElementById("discussPolicyForm").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),channel=channelById(data.get("channelId"));if(!ensureChannelChain(channel)){showMeetingNotice("Select a channel with the same locked firm as its engagement.",true);return}const split=value=>String(value||"").split(",").map(item=>item.trim()).filter(Boolean),policy=channelPolicy(channel);policy.conversationType=data.get("conversationType");policy.description=data.get("description").trim();policy.authorizedPositions=split(data.get("authorizedPositions"));policy.autoSubscribePositions=split(data.get("autoSubscribePositions"));policy.updatedAt=new Date().toISOString();channel.conversationType=policy.conversationType;channel.description=policy.description;channel.memberPositions=policy.authorizedPositions.join(", ");policy.autoSubscribePositions.forEach(position=>{if(!channelMemberships.some(member=>member.channelId===channel.id&&member.position===position&&member.active!==false))channelMemberships.push({id:crypto.randomUUID(),channelId:channel.id,position,source:"ROLE_AUTO_SUBSCRIPTION",active:true,createdAt:new Date().toISOString()})});saveDiscussControls();renderDiscussPolicyPanel();renderMeetingWorkspace();showMeetingNotice(`${channel.name} access policy saved. Production checks this policy before each API, WebSocket or SSE event.`)});renderDiscussPolicyPanel()}
const baseRenderMeetingWorkspace=renderMeetingWorkspace;
renderMeetingWorkspace=function(){syncDiscussChannels();baseRenderMeetingWorkspace();renderDiscussPolicyPanel();decorateGoogleMeetWorkspace()};
