// Email-to-ERP preview. This UI stores only connection metadata and secret
// references; IMAP/SMTP credentials, raw mail and actual delivery stay in the
// production secret manager, object store and background worker.
const emailWorkspaceStorage={servers:"pcl-crm-email-servers-v1",aliases:"pcl-crm-email-aliases-v1",threads:"pcl-crm-email-threads-v1",messages:"pcl-crm-email-messages-v1",syncRuns:"pcl-crm-email-sync-runs-v1"};
let emailServers=loadRecords(emailWorkspaceStorage.servers),emailAliases=loadRecords(emailWorkspaceStorage.aliases),emailThreads=loadRecords(emailWorkspaceStorage.threads),emailMessages=loadRecords(emailWorkspaceStorage.messages),emailSyncRuns=loadRecords(emailWorkspaceStorage.syncRuns);
const emailPreviewRoles=["Email Manager","Tax Manager","Audit Manager","Audit Supervisor","Audit Assistant","Intern"];
function saveEmailWorkspace(){Object.entries({servers:emailServers,aliases:emailAliases,threads:emailThreads,messages:emailMessages,syncRuns:emailSyncRuns}).forEach(([key,value])=>localStorage.setItem(emailWorkspaceStorage[key],JSON.stringify(value)));saveOperations()}
function emailThreadById(id){return emailThreads.find(thread=>thread.id===id)}
function emailMessageById(id){return emailMessages.find(message=>message.id===id)}
function emailAliasById(id){return emailAliases.find(alias=>alias.id===id)}
function emailRouteForAlias(alias){return alias?.routeRole||"Email Manager"}
function emailManagerAccess(role){return role==="Email Manager"}
function currentEmailPreviewRole(){return document.getElementById("emailPreviewRole")?.value||"Email Manager"}
function accessibleEmailMessages(role=currentEmailPreviewRole()){return emailMessages.filter(message=>emailManagerAccess(role)||message.routeRole===role||(role==="Audit Assistant"&&message.assignedPosition==="Audit Assistant"))}
function normaliseEmailSubject(subject){return String(subject||"").replace(/^(re|fw|fwd)\s*:\s*/i,"").trim().toLowerCase()}
function findOrCreateEmailThread(engagement,subject,contact={}){const key=normaliseEmailSubject(subject),existing=emailThreads.find(thread=>thread.engagementId===engagement.id&&thread.subjectNormalized===key);if(existing)return existing;const thread={id:crypto.randomUUID(),firmId:engagement.firmId,engagementId:engagement.id,clientName:engagement.companyName,contactName:contact.name||engagement.contact?.name||"",contactEmail:contact.email||engagement.contact?.email||"",subjectNormalized:key,createdAt:new Date().toISOString(),lastMessageAt:new Date().toISOString()};emailThreads.push(thread);return thread}
function messageIdentifier(){return `<pcl-${crypto.randomUUID()}@erp.local>`}
function emailQueueLabel(alias){return `${alias.aliasAddress} → ${alias.routeModule.replace("_"," ")} / ${alias.routeRole||"Email Manager"}`}
function showEmailNotice(message,error=false){const target=document.getElementById("emailNotice");if(!target)return;target.textContent=message;target.classList.add("show");target.style.background=error?"#fbe8e8":"";target.style.color=error?"#8b2828":"";clearTimeout(showEmailNotice.timer);showEmailNotice.timer=setTimeout(()=>target.classList.remove("show"),8000)}
function renderEmailWorkspace(){
  const section=document.getElementById("email-workspace");if(!section)return;
  const role=currentEmailPreviewRole(),visible=accessibleEmailMessages(role);
  const set=(id,value)=>{const node=document.getElementById(id);if(node)node.textContent=value};
  set("emailTotalInbox",emailMessages.filter(message=>message.direction==="INBOUND").length);
  set("emailVisibleInbox",visible.filter(message=>message.direction==="INBOUND").length);
  set("emailAliasCount",emailAliases.filter(alias=>alias.active!==false).length);
  set("emailSyncCount",emailSyncRuns.length);
  const engagementOptions=activeEngagements().map(engagement=>`<option value="${engagement.id}">${escapeHtml(engagementLabel(engagement))}</option>`).join("");
  const aliasOptions=emailAliases.filter(alias=>alias.active!==false).map(alias=>`<option value="${alias.id}">${escapeHtml(emailQueueLabel(alias))}</option>`).join("");
  ["emailIncomingEngagement","emailReplyEngagement"].forEach(id=>{const select=document.getElementById(id);if(!select)return;const prior=select.value;select.innerHTML=`<option value="">Select engagement…</option>${engagementOptions}`;if([...select.options].some(option=>option.value===prior))select.value=prior});
  const aliasSelect=document.getElementById("emailIncomingAlias");if(aliasSelect){const prior=aliasSelect.value;aliasSelect.innerHTML=`<option value="">Select configured alias…</option>${aliasOptions}`;if([...aliasSelect.options].some(option=>option.value===prior))aliasSelect.value=prior}
  const replySource=document.getElementById("emailReplySource");if(replySource){const prior=replySource.value;replySource.innerHTML=`<option value="">Select accessible email to reply…</option>${visible.filter(message=>message.direction==="INBOUND").map(message=>`<option value="${message.id}">${escapeHtml(message.subject)} · ${escapeHtml(message.from)}</option>`).join("")}`;if([...replySource.options].some(option=>option.value===prior))replySource.value=prior}
  const config=document.getElementById("emailConfigurationList");
  config.innerHTML=!emailManagerAccess(role)?'<p class="hint">Global email configuration is visible only to Email Manager.</p>':(emailServers.length?emailServers.map(server=>`<article class="email-config-row"><b>${escapeHtml(server.name)}</b><span>${escapeHtml(server.direction)} · ${escapeHtml(server.hostname)}:${escapeHtml(server.port)} · ${escapeHtml(server.security)}</span><small>Secret: ${escapeHtml(server.secretReference)}</small></article>`).join(""):'<p class="hint">No IMAP/SMTP metadata registered. Use a secret-manager reference — never paste credentials here.</p>');
  const aliases=document.getElementById("emailAliasList");
  aliases.innerHTML=!emailManagerAccess(role)?'<p class="hint">Alias administration is restricted to Email Manager.</p>':(emailAliases.length?emailAliases.map(alias=>`<article class="email-config-row"><b>${escapeHtml(alias.aliasAddress)}</b><span>${escapeHtml(alias.routeModule.replace("_"," "))} → ${escapeHtml(alias.routeRole||"Email Manager")}</span></article>`).join(""):'<p class="hint">No aliases configured.</p>');
  const inbox=document.getElementById("emailInboxList");
  if(!visible.length){inbox.innerHTML=`<div class="empty">No messages are visible to ${escapeHtml(role)}. Email Managers see the global inbox; other positions see only their routed queue or directly assigned-client replies.</div>`}
  else inbox.innerHTML=visible.slice().sort((a,b)=>new Date(b.receivedAt)-new Date(a.receivedAt)).map(message=>{
    const thread=emailThreadById(message.threadId),route=message.routeRole||"Email Manager";
    const canReply=emailManagerAccess(role)||route===role||(role==="Audit Assistant"&&message.assignedPosition==="Audit Assistant");
    const replyControl=canReply&&message.direction==="INBOUND"?`<div class="client-actions"><button data-email-action="reply" data-id="${message.id}">Reply in thread</button></div>`:"";
    return `<article class="email-message-card ${message.direction.toLowerCase()}"><div><h4>${escapeHtml(message.subject)}</h4><p><b>${message.direction==="INBOUND"?"From":"To"}:</b> ${escapeHtml(message.direction==="INBOUND"?message.from:message.to)} · ${escapeHtml(thread?.clientName||"Unlinked")}</p><p class="hint">${escapeHtml(message.receivedAt.slice(0,16).replace("T"," "))} · Thread ${escapeHtml(message.threadId.slice(0,8))} · Route: ${escapeHtml(route)}</p><p>${escapeHtml(message.body).slice(0,280)}</p></div><div><span class="pill ${message.deliveryStatus==="FAILED"?"critical":""}">${escapeHtml(message.deliveryStatus)}</span>${replyControl}</div></article>`
  }).join("");
  const restricted=!emailManagerAccess(role);["emailServerForm","emailAliasForm"].forEach(id=>{const form=document.getElementById(id);if(form)form.querySelectorAll("input,select,button").forEach(control=>control.disabled=restricted)});
}
function injectEmailWorkspace(){if(document.getElementById("email-workspace"))return;const nav=document.querySelector(".tabs"),shell=document.querySelector(".shell"),tab=document.createElement("button"),section=document.createElement("section"),before=nav.querySelector("[data-tab='production-readiness']");tab.className="tab";tab.type="button";tab.dataset.tab="email-workspace";tab.innerHTML='<svg class="nav-icon" aria-hidden="true"><use href="#icon-message" /></svg>Email';section.id="email-workspace";section.className="tab-panel";section.innerHTML=`<div class="intro"><div><h2>Email-to-ERP Workspace</h2><p>Inbound IMAP routing, secure SMTP replies and threaded Communication Hub history. Connection secrets are referenced, not stored, and Email Manager access is separate from client-team reply access.</p></div><label class="email-role-switch">Preview position<select id="emailPreviewRole">${emailPreviewRoles.map(role=>`<option>${role}</option>`).join("")}</select></label></div><div class="notice" id="emailNotice" role="status"></div><div class="metric-grid"><div class="card metric-card"><b id="emailTotalInbox">0</b><span>Inbound messages</span></div><div class="card metric-card"><b id="emailVisibleInbox">0</b><span>Visible to position</span></div><div class="card metric-card"><b id="emailAliasCount">0</b><span>Active aliases</span></div><div class="card metric-card"><b id="emailSyncCount">0</b><span>Logged sync runs</span></div></div><div class="operations-layout"><div><form id="emailServerForm" class="card form-card"><div class="section-heading"><h3>Secure IMAP / SMTP configuration</h3><span class="hint">Email Manager only</span></div><div class="grid"><label>Configuration name<input required name="name" placeholder="Firm mailbox" /></label><label>Direction<select name="direction"><option value="INBOUND_IMAP">Inbound IMAP</option><option value="OUTBOUND_SMTP">Outbound SMTP</option></select></label><label>Host<input required name="hostname" placeholder="mail.example.co.ke" /></label><label>Port<input required type="number" min="1" max="65535" name="port" value="993" /></label><label>Security<select name="security"><option>SSL/TLS</option><option>STARTTLS</option></select></label><label>Secret-manager reference<input required name="secretReference" placeholder="secret://erp/mail/imap" /></label></div><div class="actions"><button class="btn secondary" type="submit">Save secure connection metadata</button></div></form><form id="emailAliasForm" class="card form-card" style="margin-top:18px"><div class="section-heading"><h3>Alias routing</h3><span class="hint">Email Manager only</span></div><div class="grid"><label>Alias address<input required type="email" name="aliasAddress" placeholder="tax@yourfirm.co.ke" /></label><label>Route module<select name="routeModule"><option value="COMMUNICATION_HUB">Communication Hub</option><option value="TAX_QUEUE">Tax queue</option><option value="AUDIT_QUEUE">Audit queue</option><option value="HELPDESK">Help Desk</option></select></label><label class="full">Route to position<input name="routeRole" value="Tax Manager" placeholder="Tax Manager or Email Manager" /></label></div><div class="actions"><button class="btn secondary" type="submit">Add alias route</button></div></form></div><div><div class="card side-card"><div class="section-heading"><h3>Connection register</h3><span class="hint">No credentials displayed</span></div><div id="emailConfigurationList" class="email-config-list"></div></div><div class="card side-card" style="margin-top:18px"><div class="section-heading"><h3>Alias register</h3><span class="hint">Incoming routing</span></div><div id="emailAliasList" class="email-config-list"></div></div></div></div><div class="operations-layout"><form id="emailIncomingForm" class="card form-card"><div class="section-heading"><h3>Record incoming email</h3><span class="hint">Browser preview of IMAP fetch + alias routing</span></div><div class="grid"><label class="full">Engagement <span>*</span><select required id="emailIncomingEngagement" name="engagementId"></select></label><label>Received through alias <span>*</span><select required id="emailIncomingAlias" name="aliasId"></select></label><label>From <span>*</span><input required type="email" name="from" placeholder="client@example.com" /></label><label class="full">Subject <span>*</span><input required name="subject" placeholder="Request for VAT return status" /></label><label class="full">Message <span>*</span><textarea required name="body" placeholder="The inbound email body is copied into the Communication Hub timeline."></textarea></label></div><div class="actions"><button class="btn primary" type="submit">Route inbound email</button></div></form><form id="emailReplyForm" class="card form-card"><div class="section-heading"><h3>Reply in existing thread</h3><span class="hint">Preserves In-Reply-To and References</span></div><div class="grid"><label class="full">Original email <span>*</span><select required id="emailReplySource" name="sourceId"></select></label><label class="full">Reply text <span>*</span><textarea required name="body" placeholder="Authorised reply from the selected firm mailbox."></textarea></label></div><div class="actions"><button class="btn primary" type="submit">Queue SMTP reply</button></div></form></div><div class="section"><div class="section-heading"><h3>Role-filtered inbox</h3><span class="hint">Replies remain in the original Message-ID thread</span></div><div id="emailInboxList" class="email-inbox-list"></div></div>`;if(before)nav.insertBefore(tab,before);else nav.append(tab);shell.append(section);tab.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(button=>button.classList.toggle("active",button===tab));document.querySelectorAll(".tab-panel").forEach(panel=>panel.classList.toggle("active",panel===section));renderEmailWorkspace()});document.getElementById("emailPreviewRole").addEventListener("change",renderEmailWorkspace);document.getElementById("emailServerForm").addEventListener("submit",event=>{event.preventDefault();if(!emailManagerAccess(currentEmailPreviewRole()))return;const data=new FormData(event.currentTarget);emailServers.push({id:crypto.randomUUID(),name:data.get("name").trim(),direction:data.get("direction"),hostname:data.get("hostname").trim(),port:data.get("port"),security:data.get("security"),secretReference:data.get("secretReference").trim(),createdAt:new Date().toISOString()});saveEmailWorkspace();event.currentTarget.reset();renderEmailWorkspace();showEmailNotice("Connection metadata saved. Production validates IMAP/SMTP using the secret manager; no password was stored in the ERP.")});document.getElementById("emailAliasForm").addEventListener("submit",event=>{event.preventDefault();if(!emailManagerAccess(currentEmailPreviewRole()))return;const data=new FormData(event.currentTarget),address=data.get("aliasAddress").trim().toLowerCase();if(emailAliases.some(alias=>alias.aliasAddress===address)){showEmailNotice("That alias is already configured.",true);return}emailAliases.push({id:crypto.randomUUID(),aliasAddress:address,routeModule:data.get("routeModule"),routeRole:data.get("routeRole").trim()||"Email Manager",active:true,createdAt:new Date().toISOString()});saveEmailWorkspace();event.currentTarget.reset();renderEmailWorkspace();showEmailNotice(`${address} will route new mail to the selected queue.`)});document.getElementById("emailIncomingForm").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),engagement=engagementById(data.get("engagementId")),alias=emailAliasById(data.get("aliasId"));if(!engagement||!alias||alias.active===false){showEmailNotice("Select a controlled engagement and active alias.",true);return}const thread=findOrCreateEmailThread(engagement,data.get("subject"),engagement.contact),message={id:crypto.randomUUID(),threadId:thread.id,firmId:engagement.firmId,engagementId:engagement.id,aliasId:alias.id,direction:"INBOUND",internetMessageId:messageIdentifier(),inReplyTo:null,references:"",from:data.get("from").trim(),to:alias.aliasAddress,subject:data.get("subject").trim(),body:data.get("body").trim(),receivedAt:new Date().toISOString(),deliveryStatus:"RECEIVED",routeRole:emailRouteForAlias(alias),assignedPosition:alias.routeRole};try{const hub=logCommunication({subject:message.subject,communicationType:"Email",activityType:"Inbound Email",direction:"Inbound",body:message.body,staffId:message.routeRole,leadId:engagement.id,engagementId:engagement.id,firmId:engagement.firmId,serviceOffered:engagement.initialService,branchLocation:engagement.branchLocation,status:"Open",purpose:"Inbound email routed through alias",signatoryReference:""});message.communicationId=hub.id;emailMessages.push(message);thread.lastMessageAt=message.receivedAt;emailSyncRuns.push({id:crypto.randomUUID(),aliasId:alias.id,startedAt:message.receivedAt,completedAt:new Date().toISOString(),messagesFetched:1,messagesRouted:1,status:"Preview"});saveEmailWorkspace();event.currentTarget.reset();renderEmailWorkspace();renderCommunicationHub();showEmailNotice(`Inbound email routed to ${message.routeRole} and recorded in the Communication Hub. It has no QR reference.`)}catch(error){showEmailNotice(error.message,true)}});document.getElementById("emailReplyForm").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),source=emailMessageById(data.get("sourceId")),role=currentEmailPreviewRole();if(!source){showEmailNotice("Select an original inbound message.",true);return}if(!(emailManagerAccess(role)||source.routeRole===role||(role==="Audit Assistant"&&source.assignedPosition==="Audit Assistant"))){showEmailNotice("This position may only reply to mail directly routed to its assigned client work.",true);return}const engagement=engagementById(source.engagementId),thread=emailThreadById(source.threadId),message={id:crypto.randomUUID(),threadId:source.threadId,firmId:source.firmId,engagementId:source.engagementId,direction:"OUTBOUND",internetMessageId:messageIdentifier(),inReplyTo:source.internetMessageId,references:[source.references,source.internetMessageId].filter(Boolean).join(" "),from:"authorised-firm-mailbox",to:source.from,subject:`Re: ${source.subject.replace(/^Re:\s*/i,"")}`,body:data.get("body").trim(),receivedAt:new Date().toISOString(),deliveryStatus:"QUEUED",routeRole:source.routeRole,assignedPosition:role};try{const hub=logCommunication({subject:message.subject,communicationType:"Email",activityType:"Outbound Email",direction:"Outbound",body:message.body,staffId:role,leadId:engagement.id,engagementId:engagement.id,firmId:engagement.firmId,serviceOffered:engagement.initialService,branchLocation:engagement.branchLocation,status:"Open",purpose:"Threaded SMTP reply",signatoryReference:""});message.communicationId=hub.id;emailMessages.push(message);thread.lastMessageAt=message.receivedAt;saveEmailWorkspace();event.currentTarget.reset();renderEmailWorkspace();renderCommunicationHub();showEmailNotice("Threaded SMTP reply queued. Production sends it with In-Reply-To and References headers through the firm’s SMTP service.")}catch(error){showEmailNotice(error.message,true)}});document.getElementById("emailInboxList").addEventListener("click",event=>{const button=event.target.closest("button[data-email-action='reply']"),message=emailMessageById(button?.dataset.id);if(!message)return;const select=document.getElementById("emailReplySource");select.value=message.id;document.getElementById("emailReplyForm").scrollIntoView({behavior:"smooth",block:"center"})});renderEmailWorkspace()}
document.head.insertAdjacentHTML("beforeend",`<style>.email-role-switch{min-width:180px;font-size:.85rem}.email-config-list,.email-inbox-list{display:grid;gap:10px}.email-config-row{display:grid;gap:3px;padding:12px;border-bottom:1px solid #e6ece8}.email-config-row span,.email-config-row small{color:#567065}.email-message-card{background:#fff;border:1px solid #dfe8e3;border-left:5px solid #2d7558;border-radius:10px;padding:15px;display:flex;justify-content:space-between;gap:14px}.email-message-card.outbound{border-left-color:#4b7298}.email-message-card h4{margin:0 0 6px}.email-message-card p{margin:5px 0}@media(max-width:700px){.email-message-card{display:block}.email-role-switch{width:100%;margin-top:12px}}</style>`);
